// Üretilen dosya: tool/ozgun/uret.py. Ekonomi ve Finans · Mikroekonomi: tüketici ve üretici kuramı (orta).
const ozEconomics6Orta = <(String, String, List<String>, String)>[
  ('Her sepetin en az kendisi kadar iyi olduğunu söyleyen ve çoğu zaman önemsiz görülse de tercih ilişkisinin tanımında yer alan varsayım hangisidir?', 'Yansımalılık', ['Geçişlilik ilkesi', 'Monotonluk', 'Tamlık'], 'Yansımalılık (refleksiflik), her A sepeti için A\'nın en az A kadar iyi olduğunu söyleyen biçimsel bir koşuldur.'),
  ('Bir kişi her gün farklı bir sırayla "elma > armut", "armut > muz" ve "muz > elma" diye seçim yapıyor. Bu kişinin tercihleri için en doğru yorum hangisidir?', 'Geçişlilik ihlal edildiği için en iyi seçim tanımlanamaz.', ['Tercihler dışbükey olduğu için tutarlıdır.', 'Tercihler tam olmadığı için karşılaştırma yapılamamıştır.', 'Monotonluk ihlal edildiği için kayıtsızlık eğrisi pozitif eğimlidir.'], 'Döngüsel tercihlerde her seçenekten daha iyisi bulunur; bu yüzden en çok tercih edilen bir seçenek yoktur.'),
  ('Yerel doyumsuzluk varsayımının tüketici dengesi açısından en önemli sonucu hangisidir?', 'Tüketici en iyi seçimde gelirinin tamamını harcar.', ['Tüketici her iki maldan da eşit miktar alır.', 'Tüketici yalnızca bir mal satın alır.', 'Tüketicinin talebi fiyatlardan ve gelirden bağımsız olur.'], 'Her sepetin çok yakınında daha iyi bir sepet varsa, bütçenin içinde kalan bir nokta en iyi olamaz; seçim bütçe doğrusunun üzerinde olur.'),
  ('Kesin dışbükey tercihlere sahip bir tüketici için doğrusal bir bütçe doğrusundaki en iyi seçim hakkında ne söylenebilir?', 'Tektir; birden fazla en iyi sepet olamaz.', ['Her zaman bütçe doğrusunun eksenleri kestiği köşelerden birindedir.', 'Her zaman bütçenin tam ortasındadır.', 'Sonsuz sayıda en iyi sepet vardır.'], 'Kesin dışbükey kayıtsızlık eğrileri doğrusal bir bütçe kümesine yalnız bir noktada değebilir; bu yüzden talep edilen sepet tektir.'),
  ('Bir tüketicinin tercihleri U = x·y fonksiyonuyla gösteriliyor. Aşağıdaki fonksiyonlardan hangisi aynı tercihleri göstermez?', 'V = x + y', ['V = 2xy + 5', 'V = ln x + ln y', 'V = (xy)²'], 'Pozitif monoton dönüşümler aynı sıralamayı korur. x + y toplaması ise farklı bir sıralama verir; örneğin (1,4) ile (2,2) sepetlerini farklı sıralar.'),
  ('Fayda fonksiyonuna pozitif monoton bir dönüşüm uygulandığında aşağıdakilerden hangisi değişmeden kalır?', 'Marjinal ikame oranı', ['Bir malın marjinal faydası', 'Fayda düzeylerinin sayısal değeri', 'İki sepet arasındaki fayda farkı'], 'Monoton dönüşüm iki malın marjinal faydalarını aynı oranda değiştirir; oranları olan MRS ve dolayısıyla kayıtsızlık eğrilerinin biçimi korunur.'),
  ('Kayıtsızlık eğrisi analizini geliştirerek tüketici kuramını ölçülebilir fayda varsayımından kurtaran ordinal yaklaşım 1934\'te hangi iki iktisatçının ortak makalesiyle yaygınlaştı?', 'John Hicks ve Roy Allen', ['Alfred Marshall ve Arthur Pigou', 'Léon Walras ve Vilfredo Pareto', 'Paul Samuelson ve Robert Solow'], 'Hicks ile Allen\'ın 1934 tarihli \'A Reconsideration of the Theory of Value\' makalesi, ordinal fayda ve marjinal ikame oranı kavramlarını öne çıkardı.'),
  ('Ordinal fayda çerçevesinde azalan marjinal fayda varsayımının yerini alan ve kayıtsızlık eğrilerinin biçimini belirleyen ilke hangisidir?', 'Azalan marjinal ikame oranı', ['Azalan ölçeğe göre getiri ilkesi', 'Artan fırsat maliyeti', 'Azalan ortalama ürün'], 'Marjinal fayda dönüşümle değişebildiği için ordinal kuramda anlamlı değildir; onun yerine MRS\'nin azalması kullanılır.'),
  ('U(x, y) = min(x, 2y) fayda fonksiyonuna sahip bir tüketici en verimli tüketimde iki malı hangi oranda tüketir?', 'Her 2 birim x için 1 birim y', ['Her 1 birim x için 2 birim y, yani y = 2x', 'İki maldan eşit miktar', 'Yalnızca x malını'], 'Köşede x = 2y olur; yani x miktarı y\'nin iki katıdır. Fazladan x ya da y faydayı artırmaz.'),
  ('U = x² · y fayda fonksiyonu için marjinal ikame oranı (MUx/MUy) hangi ifadeye eşittir?', '2y/x', ['y/(2x)', '2x/y', 'x/y'], 'MUx = 2xy, MUy = x²; oranları 2xy/x² = 2y/x olur.'),
  ('U = ln x + y biçimindeki yarı doğrusal (kuasi-lineer) bir fayda fonksiyonunda marjinal ikame oranı neye bağlıdır?', 'Yalnızca x miktarına', ['Yalnızca y miktarına', 'Hem x hem y miktarına', 'Her noktada sabittir'], 'MUx = 1/x, MUy = 1; MRS = 1/x olup y\'den bağımsızdır. Bu yüzden kayıtsızlık eğrileri birbirinin dikey kaydırılmış kopyalarıdır.'),
  ('Bir tüketici 1 birim peynir için 3 birim ekmekten vazgeçmeye razıdır; piyasada 1 birim peynir 2 birim ekmek fiyatındadır. Faydasını artırmak için ne yapmalıdır?', 'Daha çok peynir, daha az ekmek almalıdır.', ['Daha çok ekmek almalı ve peynir tüketimini kısmalıdır.', 'Tüketimini değiştirmemelidir.', 'Her iki maldan da daha az almalıdır.'], 'Tüketicinin peynire biçtiği değer (3 ekmek) piyasa maliyetinden (2 ekmek) yüksektir; peynire kaydıkça fayda artar.'),
  ('U = min(2x, 3y) faydasına sahip bir tüketicinin köşe noktalarını birleştiren doğrunun denklemi hangisidir?', 'y = (2/3)x', ['y = (3/2)x', 'y = x', 'y = (2/3)x + 3'], 'Köşede 2x = 3y olur; buradan y = 2x/3 çıkar.'),
  ('Kayıtsızlık eğrileri orijine göre içbükey olan bir tüketicinin doğrusal bir bütçeyle seçimi hakkında ne söylenebilir?', 'Bir köşe çözümü seçer; yalnızca bir malı alır.', ['Her zaman iki maldan eşit miktarda alarak dengeye ulaşır.', 'Bütçesinin tamamını harcamaz.', 'Teğet noktayı seçer.'], 'İçbükey eğrilerde teğet nokta faydayı en aza indirir; en iyi seçim eksenlerden birinde, yani uç noktalarda bulunur.'),
  ('Geliri 4.000 TL olan bir haneye yalnızca gıdada kullanılabilen 1.000 TL\'lik kupon veriliyor. Yatay eksende gıda varken hanenin bütçe kümesi için hangisi doğrudur?', 'En üstte 1.000 TL\'lik gıdaya kadar yatay bir parça oluşur, sonra eski eğimle iner.', ['Bütçe doğrusu her noktada 1.000 TL kadar dışa doğru tam olarak paralel kayar.', 'Bütçe doğrusu gıda ekseni etrafında içe döner.', 'Bütçe doğrusu değişmez.'], 'Hane kuponu başka mala harcayamaz; diğer mallara en çok 4.000 TL ayırabilir. Bu yüzden 1.000 TL\'lik gıdaya kadar yatay bir parça çıkar.'),
  ('X malının fiyatı 10 TL iken bu mala birim başına 5 TL özel tüketim vergisi konuyor. Gelir ve Y\'nin fiyatı sabitse bütçe doğrusu nasıl değişir?', 'Y eksenindeki kesişim sabit kalır, X eksenindeki kesişim içe kayar.', ['Doğru içeri doğru paralel kayar.', 'X eksenindeki kesişim sabit kalırken Y eksenindeki kesişim içe doğru kayar.', 'Doğru dışa doğru döner.'], 'Vergi yalnızca X\'in fiyatını 15 TL\'ye çıkarır; bu yüzden doğru Y ekseni üzerindeki nokta etrafında içe döner.'),
  ('Bir spor salonu üyelik için ayda 200 TL alıp her girişte 5 TL istiyor; üye olmayanlar ise her giriş için 15 TL ödüyor. Bir kişi ayda kaç girişten fazla gidecekse üye olmak daha ucuzdur?', '20', ['10', '13,3', '40'], 'Üyeliğin maliyeti 200 + 5x, üye olmamanınki 15x\'tir. 15x = 200 + 5x eşitliğinden x = 20 bulunur; 20\'nin üzerinde üyelik daha ucuzdur.'),
  ('Cobb-Douglas fayda fonksiyonuna sahip bir tüketicide X malının fiyatı iki katına çıkarsa X\'e yapılan toplam harcama nasıl değişir?', 'Değişmez.', ['İki katına çıkar.', 'Yarıya iner.', 'Dört katına çıkar.'], 'Cobb-Douglas tercihlerde her mala gelirin sabit bir payı harcanır; fiyat iki katına çıkınca miktar yarıya iner, harcama aynı kalır.'),
  ('Bir tüketici için bütün tüketim noktalarında MUx/MUy oranı Px/Py oranından büyükse dengede ne gözlenir?', 'Tüketici bütün gelirini X\'e harcar.', ['Tüketici bütün gelirini Y\'ye harcar.', 'Tüketici iki maldan eşit miktar alır.', 'Tüketici gelirinin bir kısmını harcamaz.'], 'X\'e harcanan her lira her noktada Y\'ye harcanandan daha çok fayda getiriyorsa, tüketici köşe çözümüne gider ve yalnızca X alır.'),
  ('Köşe çözümünde tüketicinin hiç satın almadığı mal için hangi koşul geçerlidir?', 'O mala harcanan son liranın marjinal faydası, alınan malınkinden yüksek değildir.', ['O malın marjinal faydası sıfırdır ve tüketici o maldan doymuştur.', 'O malın fiyatı sıfırdır.', 'O mal mutlaka bir düşük maldır.'], 'Köşede eşitlik değil eşitsizlik koşulu geçerlidir: alınmayan malın lira başına marjinal faydası diğerininkinden büyük olamaz.'),
  ('Yarı doğrusal (kuasi-lineer) fayda fonksiyonu U = v(x) + y olan bir tüketicide gelir artarsa (iç çözüm sürerken) X talebine ne olur?', 'Değişmez; artan gelirin tamamı Y\'ye gider.', ['Gelirle aynı oranda artar.', 'Azalır; çünkü bu tercihlerde X her zaman düşük maldır.', 'Önce artar, sonra azalır.'], 'Kuasi-lineer faydada X\'in talebi yalnız fiyatlara bağlıdır; iç çözümde ek gelir doğrusal mal olan Y\'ye harcanır.'),
  ('Bütçe doğrusu üzerindeki bir noktada kayıtsızlık eğrisi bütçe doğrusunu kesiyorsa (teğet değilse) bu nokta için ne söylenir?', 'Bütçe doğrusu boyunca bir yöne kayarak fayda artırılabilir.', ['Tüketicinin bu bütçeyle ulaşabileceği en iyi seçim noktasıdır.', 'Tüketicinin satın alamayacağı bir sepettir.', 'İki malın tam tamamlayıcı olduğunu gösterir.'], 'Kesişim noktasında MRS fiyat oranından farklıdır; daha yüksek bir kayıtsızlık eğrisine ulaşmak için bütçe üzerinde kayma yapılabilir.'),
  ('Bir tüketicinin X\'e olan Marshall talebi x = 0,4m/px biçimindedir. Gelir 2.000 TL\'den 2.500 TL\'ye çıkarken px 8 TL\'de sabit kalırsa X talebi kaç birim artar?', '25', ['100', '125', '62,5'], 'Önce 0,4 × 2.000 / 8 = 100, sonra 0,4 × 2.500 / 8 = 125 birim; artış 25 birimdir.'),
  ('Dolaylı fayda fonksiyonu v(p, m) için hangisi doğrudur?', 'Gelirde artan, fiyatlarda artmayandır.', ['Gelirde azalan, fiyatlarda artandır.', 'Hem gelirde hem de bütün fiyatlarda artan bir fonksiyondur.', 'Gelirden bağımsızdır.'], 'Daha çok gelir bütçe kümesini genişletir, daha yüksek fiyat daraltır; bu yüzden v gelirle artar, fiyatla artmaz.'),
  ('Dolaylı fayda fonksiyonunun gelire göre türevi (∂v/∂m) ekonomik olarak neyi ölçer?', 'Gelirin marjinal faydasını', ['Bir malın marjinal faydasını', 'Talebin gelir esnekliğini', 'Marjinal tüketim eğilimini'], '∂v/∂m bir lira ek gelirin sağlayacağı ek faydadır; optimizasyondaki Lagrange çarpanına eşittir.'),
  ('Bir malın Hicks talep eğrisinin eğimi için hangisi her zaman doğrudur?', 'Pozitif değildir.', ['Pozitiftir.', 'Malın normal ya da düşük olmasına göre işaret değiştirir.', 'Sıfırdır.'], 'İkame etkisi her zaman negatif (pozitif olmayan) olduğundan telafi edilmiş talep eğrisi asla yukarı eğimli olamaz; Giffen durumu yalnız Marshall talebinde görülebilir.'),
  ('Harcamayı en aza indirme ile faydayı en çoklaştırma problemlerinin aynı sepeti verdiğini söyleyen ilişkiye ne ad verilir?', 'Tüketici kuramında dualite', ['Açıklanmış tercih', 'Pareto etkinliği', 'Ölçek ekonomisi ve kapsam ekonomisi ilişkisi'], 'Dualite gereği v(p, e(p, u)) = u ve e(p, v(p, m)) = m eşitlikleri sağlanır; iki problem birbirinin aynası gibidir.'),
  ('Fayda fonksiyonu U = xy olan bir tüketici için harcama fonksiyonu e = 2√(px·py·u) biçimindedir. px = 4, py = 1 ve u = 25 iken bu fayda düzeyine ulaşmak için gereken en düşük harcama kaç TL\'dir?', '20', ['10', '25', '100'], 'e = 2√(4 × 1 × 25) = 2 × 10 = 20 TL.'),
  ('Harcama fonksiyonu fiyatlar açısından hangi biçimdedir?', 'Bütün fiyatlar iki katına çıkarsa iki katına çıkar.', ['Bütün fiyatlar iki katına çıkarsa değişmez.', 'Bütün fiyatlar iki katına çıkarsa dört katına çıkar.', 'Bütün fiyatlar iki katına çıkarsa yarıya iner.'], 'e(p, u) fiyatlarda birinci dereceden homojendir; aynı sepet iki katı paraya mal olur.'),
  ('Marshall talebi x(p, m) ile Hicks talebi h(p, u) arasındaki doğru eşitlik hangisidir?', 'h(p, u) = x(p, e(p, u))', ['x(p, m) = h(p, m)', 'h(p, u) = x(p, u)', 'x(p, m) = e(p, h(p, m)) + m'], 'Hicks talebi, geliri tam o fayda düzeyine ulaştıracak harcama kadar alınarak hesaplanan Marshall talebine eşittir.'),
  ('Slutsky yaklaşımında ikame etkisi hesaplanırken tüketicinin geliri hangi ölçüte göre telafi edilir?', 'Eski sepeti yeni fiyatlarla tam olarak satın alabilecek biçimde', ['Eski fayda düzeyine yeni fiyatlarla ulaşabilecek biçimde', 'Fiyat değişiminden önceki nominal gelir değişmeyecek biçimde', 'Bütün fiyatlar aynı oranda değişecek biçimde'], 'Slutsky telafisi satın alma gücünü sabit tutar; Hicks telafisi ise fayda düzeyini sabit tutar.'),
  ('Giffen malında fiyat düştüğünde talep edilen miktarın da düşmesi için hangi koşul gerekir?', 'Negatif gelir etkisinin ikame etkisinden büyük olması', ['İkame etkisinin sıfır olması', 'Malın normal mal olması', 'Gelir etkisinin pozitif ve ikame etkisinden büyük olması'], 'Giffen malı düşük maldır ve gelir etkisi ikame etkisini aşacak kadar güçlüdür; bu yüzden toplam etki ters işaret alır.'),
  ('Bir malın gelir etkisi büyük ölçüde o malın bütçedeki payına bağlıdır. Tuz gibi bütçede çok küçük pay tutan bir malın fiyatı değiştiğinde ne beklenir?', 'Gelir etkisi önemsiz kalır.', ['Gelir etkisi ikame etkisinden büyük olur.', 'Mal Giffen malına dönüşür.', 'İkame etkisi sıfır olur.'], 'Slutsky denkleminde gelir etkisi tüketilen miktarla çarpılır; bütçede küçük pay tutan malın fiyat değişimi satın alma gücünü çok az etkiler.'),
  ('Cobb-Douglas tercihlere sahip bir tüketicide X\'in fiyatı değiştiğinde (dikey eksende Y varken) fiyat-tüketim eğrisi nasıl görünür?', 'Yatay bir doğru', ['Dikey bir doğru', 'Orijinden geçen bir ışın', 'Negatif eğimli bir doğru'], 'Cobb-Douglas\'ta Y talebi yalnızca gelire ve Py\'ye bağlıdır; X\'in fiyatı değişince Y değişmez, bu yüzden eğri yataydır.'),
  ('Cobb-Douglas tercihlere sahip bir tüketicinin bir mal için Engel eğrisi (gelir–miktar ilişkisi) nasıldır?', 'Orijinden geçen doğrusal bir eğri', ['Önce artan, belli bir gelirden sonra azalan bir eğri', 'Yatay bir doğru', 'Giderek dikleşen bir eğri'], 'x = a·m/px olduğu için miktar gelirle orantılı artar; gelir esnekliği her yerde 1\'dir.'),
  ('Talep fonksiyonu Q = 100 − 2P olan bir malda fiyat 20 TL iken talebin nokta fiyat esnekliği yaklaşık kaçtır?', '−0,67', ['−1,5', '−0,400', '−2,0'], 'P = 20\'de Q = 60\'tır; ε = (dQ/dP)·(P/Q) = −2 × 20/60 ≈ −0,67.'),
  ('Talep fonksiyonu Q = 50 · P^(−2) biçiminde olan bir malın fiyat esnekliği için hangisi doğrudur?', 'Her fiyatta −2\'dir.', ['Fiyat yükseldikçe sıfıra yaklaşır.', 'Yalnızca P = 1\'de −2\'dir.', 'Her fiyatta −50\'dir.'], 'Q = A·P^b biçimindeki talep sabit esneklikli talep eğrisidir; esneklik her noktada üs olan b\'ye eşittir.'),
  ('Bir araştırmacı talebi ln Q = 3 − 0,5 ln P + 1,2 ln M biçiminde tahmin etmiştir (M gelir). Bu malın gelir esnekliği ve türü için doğru eşleştirme hangisidir?', '1,2; lüks mal', ['0,5; zorunlu mal', '−0,5; düşük mal', '3; lüks mal'], 'Log-doğrusal modelde katsayılar doğrudan esnekliktir; gelir esnekliği 1,2 > 1 olduğundan mal lükstür.'),
  ('Talebin fiyat esnekliği −0,4 olan bir malın fiyatı %10 artarsa tüketicilerin bu mala yaptığı toplam harcama yaklaşık nasıl değişir?', 'Yaklaşık %5,6 artar.', ['Yaklaşık %4 azalır.', 'Yaklaşık %14 artar; çünkü fiyat ve miktar birlikte artar.', 'Değişmez.'], 'Miktar yaklaşık %4 azalır; yeni harcama 1,10 × 0,96 ≈ 1,056 katıdır, yani yaklaşık %5,6 artar.'),
  ('Engel toplama koşuluna göre bütçe paylarıyla ağırlıklandırılmış gelir esneklikleri toplamı kaça eşittir?', '1', ['0', '−1', 'Mal sayısına'], 'Gelirdeki her artış bir malın tüketimine gitmek zorunda olduğundan Σ sᵢ·ηᵢ = 1 olur.'),
  ('Marshall talebi sıfırıncı dereceden homojen olduğundan bir malın kendi fiyat esnekliği, çapraz fiyat esneklikleri ve gelir esnekliği toplamı kaça eşittir?', '0', ['1', '−1', 'Bütçe payına'], 'Euler teoremi gereği homojenlik koşulu Σ εᵢⱼ + ηᵢ = 0 biçiminde yazılır.'),
  ('İki mallı bir modelde X\'in kendi fiyat esnekliği −0,8 ve Y\'ye göre çapraz esnekliği 0,3\'tür. Homojenlik koşuluna göre X\'in gelir esnekliği kaçtır?', '0,5', ['1,1', '−0,5', '0,3'], '−0,8 + 0,3 + η = 0 eşitliğinden η = 0,5 bulunur.'),
  ('Bir tüketici A sepetini seçtiği gün B sepetini de alabilecek durumdaydı. Açıklanmış tercihin zayıf aksiyomuna göre bu kişi B\'yi seçtiği başka bir günde ne olmamalıdır?', 'A sepetini alabilecek durumda olmamalıdır.', ['B sepetinin fiyatı yükselmiş olmamalıdır.', 'Geliri artmış olmamalıdır.', 'A sepetinden daha ucuz bir sepet bulunmamalıdır.'], 'A, B\'ye doğrudan açıklanmış tercihlidir. B seçildiğinde A da alınabiliyorsa B de A\'ya açıklanmış tercihli olur; bu WARP ihlalidir.'),
  ('Açıklanmış tercihin güçlü aksiyomu (SARP) zayıf aksiyomdan (WARP) neyle ayrılır?', 'Dolaylı yoldan açıklanan tercihleri de kapsayarak geçişliliği şart koşar.', ['Yalnızca iki mallı durumlar için geçerlidir.', 'Fayda fonksiyonunun ölçülebilir olmasını gerektirir.', 'Bütçenin tam harcanmadığı durumları dışlar.'], 'SARP, A\'nın B\'ye, B\'nin C\'ye açıklanmış tercihli olduğu zincirlerde C\'nin A\'ya açıklanmış tercihli olmamasını ister.'),
  ('Bir çalışanın aylık geliri bir yılda %30 artmış, sabit sepete dayalı Laspeyres fiyat endeksi ise %20 yükselmiştir. Çalışanın refahı için en güvenilir sonuç hangisidir?', 'Eski sepetini hâlâ alabildiği için en az eskisi kadar iyidir.', ['Kesinlikle eskisinden daha kötü durumdadır.', 'Refahı hakkında endeks bilgisinden hiçbir sonuç çıkarılamaz.', 'Refahı tam olarak %10 artmıştır.'], 'Gelir artışı Laspeyres endeksinden büyükse eski sepet yeni fiyatlarla alınabilir; tüketici en az eskisi kadar iyi durumdadır.'),
  ('Aynı kişi (U = C · L, saat ücreti 20 TL, günde 24 saat) günlük 120 TL\'lik emek dışı gelir elde etmeye başlarsa çalışma süresi kaç saate iner?', '9', ['12', '15', '6'], 'Tam gelir 24 × 20 + 120 = 600 TL; boş zaman 300 / 20 = 15 saat, çalışma 24 − 15 = 9 saattir.'),
  ('Milton Friedman\'ın savunduğu, belirli bir gelirin altındakilere vergi alınmak yerine ödeme yapılmasını öngören düzenlemenin emek arzı açısından klasik yardımlara üstünlüğü ne olarak gösterilir?', 'Kazanılan her ek liranın bir kısmının kişide kalması', ['Herkesin gelirinden bağımsız olarak aynı tutarda vergi ödemesi', 'Çalışanların ücretlerinin devletçe belirlenmesi', 'Yardımın yalnızca ayni olarak verilmesi'], 'Negatif gelir vergisinde yardım kazançla birlikte yavaş azalır; örtük vergi oranı %100\'ün altında kaldığı için çalışma teşviki korunur.'),
  ('Ücretli bir çalışanın gelir vergisi oranı artınca çalışma saatlerinin değişmemesi en iyi nasıl açıklanır?', 'Ters yönlü ikame ve gelir etkilerinin birbirini dengelemesiyle', ['Vergilerin bütçe doğrusunu etkilememesiyle', 'Boş zamanın bu kişi için düşük mal olmasıyla', 'Çalışanın rezervasyon ücretinin sıfır olmasıyla'], 'Net ücretin düşmesi ikame etkisiyle çalışmayı azaltır, gelir kaybı ise gelir etkisiyle artırır; iki etki eşitse saatler değişmez.'),
  ('Tasarruf eden bir kişi için faiz oranının yükselmesinin bugünkü tüketime etkisi neden belirsizdir?', 'İkame etkisi tüketimi azaltırken gelir etkisi artırır.', ['İkame etkisi de gelir etkisi de bugünkü tüketimi kesin olarak artırır.', 'Faiz oranı yalnızca borçluları etkiler.', 'Tasarruf edenlerin bütçe doğrusu faizle değişmez.'], 'Bugünkü tüketim göreli olarak pahalanır (ikame etkisi), ama tasarruf sahibinin faiz geliri artar (gelir etkisi).'),
  ('Borç alma faizinin borç verme faizinden yüksek olduğu bir durumda zamanlar arası bütçe doğrusu nasıldır?', 'Donatım noktasında kırılır; borçlanma tarafında daha diktir.', ['Tamamen doğrusal kalır.', 'Donatım noktasında kırılır; tasarruf tarafında daha diktir.', 'Yatay ve dikey iki parçadan oluşan dik açılı bir biçim alır.'], 'Borçlanırken bugünkü tüketimin bedeli 1 + r_borç, tasarruf ederken 1 + r_mevduat olur; borç tarafı daha dik eğimlidir.'),
  ('Aynı kişi (u(w) = √w; %50 olasılıkla 100 TL, %50 olasılıkla 0 TL) için piyangonun kesinlik eşdeğeri kaç TL\'dir?', '25', ['50', '5', '12,5'], 'Kesinlik eşdeğeri, faydası beklenen faydaya eşit kesin tutardır: √CE = 5 olduğundan CE = 25 TL.'),
  ('Fayda fonksiyonu u(w) = ln w olan bir kişinin mutlak riskten kaçınma derecesi serveti arttıkça nasıl değişir?', 'Azalır.', ['Artar.', 'Sabit kalır.', 'Önce artar, sonra azalır.'], 'u\' = 1/w, u\'\' = −1/w²; mutlak ölçü 1/w\'dir ve servet arttıkça azalır. Göreli riskten kaçınma ise sabit 1\'dir.'),
  ('Bir torbada 30 kırmızı top ve oranı bilinmeyen 60 siyah-sarı top vardır. İnsanların çoğunun olasılığı bilinen kırmızıya bahis yapmayı seçmesi hangi eğilimi gösterir?', 'Belirsizlikten (muğlaklıktan) kaçınma', ['Riski sevme', 'Kayıp sevgisi', 'Sahiplik (bağış) etkisi'], 'Ellsberg paradoksunda kişiler olasılığı bilinen riskleri olasılığı bilinmeyen belirsizliğe tercih eder.'),
  ('Kesin 500 TL kayıp ile %50 olasılıkla 1.000 TL kayıp ya da hiç kayıp seçenekleri arasında çoğu insanın kumarı seçmesi beklenti kuramında nasıl açıklanır?', 'Kayıp bölgesinde değer fonksiyonu dışbükey olduğu için insanlar risk alır.', ['İnsanlar her durumda riskten kaçınır.', 'Kesin kayıp beklenen değeri daha düşük olduğu için reddedilir.', 'Kumarın beklenen değeri kesin kayıptan daha yüksek olduğu için seçilir.'], 'İki seçeneğin beklenen değeri eşittir; ancak kayıplarda risk arayışı kişiyi kesin kayıptan kaçınıp kumara yöneltir.'),
  ('İnsanların piyango bileti alırken aynı zamanda sigorta da yaptırması beklenti kuramında hangi özellikle açıklanır?', 'Düşük olasılıklara gerçekte olduğundan fazla ağırlık verilmesi', ['Kayıplarda riskten kaçınma', 'Referans noktasının her seçimden sonra sürekli değişmesi', 'Yüksek olasılıklara fazla ağırlık verilmesi'], 'Olasılık ağırlıklandırma fonksiyonu küçük olasılıkları şişirir; hem çok küçük büyük ödül şansı hem de küçük felaket riski olduğundan büyük algılanır.'),
  ('Bir sinemada küçük mısır 30 TL, büyük mısır 70 TL iken çoğu kişi küçüğü alıyor. Araya 65 TL\'lik orta boy eklenince büyük mısırın satışları artıyor. Bu durum hangi etkiyle açıklanır?', 'Tuzak (asimetrik baskınlık) etkisi', ['Gelir etkisi', 'Veblen etkisi', 'Yansıma etkisi ve kayıptan kaçınma'], 'Büyük boydan açıkça kötü olan orta boy seçeneği büyüğü daha cazip gösterir; ilgisiz bir seçenek tercihleri değiştirir.'),
  ('Bir kişi bugün 100 TL\'yi yarın 110 TL\'ye tercih ediyor, ama 30 gün sonraki 100 TL yerine 31 gün sonraki 110 TL\'yi seçiyor. Bu tercih örüntüsü hangi iskonto biçimiyle tutarlıdır?', 'Hiperbolik iskonto', ['Üstel (sabit oranlı) iskonto', 'Sıfır iskonto', 'Negatif iskonto'], 'Hiperbolik iskontoda yakın gelecekteki gecikmeye çok, uzak gelecekteki aynı gecikmeye az ceza verilir; bu da zaman tutarsızlığına yol açar.'),
  ('β-δ modelinde β = 0,5 ve δ = 1 olan bir kişi için yarın alınacak 100 TL\'nin bugünkü değeri kaç TL\'dir?', '50', ['100', '25', '75,0'], 'Gelecek dönemdeki ödül β·δ ile çarpılır: 100 × 0,5 × 1 = 50 TL.'),
  ('Diyet yapmak isteyen birinin evine hiç tatlı almaması ya da kumarbazın kendini kumarhanelere girişten men ettirmesi hangi davranışa örnektir?', 'Taahhüt (bağlanma) mekanizması', ['Fiyat farklılaştırması', 'Sürü davranışı', 'Ters seçim'], 'Zaman tutarsızlığının farkında olan bilinçli kişiler gelecekteki seçeneklerini kendi kendilerine kısıtlar; Odysseus\'un kendini direğe bağlatması klasik örnektir.'),
  ('Bandwagon etkisinin bulunduğu bir piyasada fiyat düştüğünde piyasa talebi, bu etkinin olmadığı duruma göre nasıl tepki verir?', 'Daha güçlü tepki verir; talep daha esnektir.', ['Daha zayıf tepki verir; talep daha inelastiktir.', 'Hiç tepki vermez.', 'Ters yönde tepki verir.'], 'Fiyat düşünce yeni alıcılar ürünü alır; bu da başkalarını alıma özendirir. Ek tepki talebi daha esnek kılar.'),
  ('Ağ etkisi güçlü olan piyasalarda teknik olarak daha iyi bir standardın yayılamayıp daha eski bir standardın sürmesi hangi kavramla açıklanır?', 'Kilitlenme', ['Ölçeğe göre azalan getiri', 'Gösteriş tüketimi', 'Ters seçim'], 'Kullanıcıların çoğu mevcut standarda bağlı olduğundan geçiş maliyeti yüksektir; QWERTY klavye bu tartışmada sıkça örnek verilir.'),
  ('Becker\'ın zaman tahsisi kuramına göre ücretler yükseldikçe hangi tür tüketimin göreli olarak pahalanması beklenir?', 'Çok zaman alan tüketim faaliyetlerinin', ['Az zaman alan hazır ürünlerin', 'Bütün malların aynı oranda ve aynı anda', 'Yalnızca dayanıklı malların'], 'Ücret arttıkça zamanın fırsat maliyeti artar; uzun süren faaliyetlerin tam fiyatı hızlı ve hazır seçeneklere göre yükselir.'),
  ('Bir haneye belirli bir tutarda nakit yerine aynı değerde gıda kolisi verilmesi tüketici kuramına göre hanenin refahını nasıl etkiler?', 'Nakitten daha iyi olamaz; en fazla nakit kadar iyidir.', ['Her zaman nakitten daha iyidir.', 'Her zaman nakitten daha kötüdür.', 'Hanenin gelirinden bağımsız olarak her durumda nakitle tamamen aynıdır.'], 'Nakit, gıda kolisinin bütçe kümesini de içeren daha geniş bir küme sunar; hane zaten o kadar gıda alıyorsa iki yardım eşdeğerdir.'),
  ('Ayni gıda yardımının nakit yardımla tam olarak aynı refahı sağlaması hangi durumda gerçekleşir?', 'Hane yardım tutarından fazla gıdayı zaten satın almak istiyorsa', ['Hane gıdaya yardımdan önce hiç para harcamıyorsa', 'Gıda bir Veblen malı ise', 'Gıdanın fiyatı sıfırsa'], 'Bu durumda ayni yardım \'kenar dışı\' kalır; hane gıda alımını yardım kadar azaltıp kalan parayı başka mallara harcar.'),
  ('Devletin aynı vergi gelirini birim başına özel tüketim vergisi yerine götürü gelir vergisiyle toplaması tüketici açısından neden daha iyidir?', 'Götürü vergi göreli fiyatları bozmadığı için ikame etkisi doğurmaz.', ['Götürü vergi tüketicinin bütçesini hiç küçültmez ve gelir etkisi doğurmaz.', 'Özel tüketim vergisi gelir etkisi yaratmaz.', 'Götürü vergi her zaman daha az vergi geliri sağlar.'], 'Aynı gelir için götürü verginin bütçe doğrusu, vergili sepetten geçer ama eski eğimini korur; tüketici daha yüksek bir kayıtsızlık eğrisine ulaşabilir.'),
  ('Bir malın fiyatını sübvanse etmek yerine aynı maliyette nakit destek verilirse sübvanse edilen malın tüketimi için genellikle ne beklenir?', 'Daha az olur.', ['Daha fazla olur.', 'Aynı kalır.', 'Sıfıra iner.'], 'Fiyat sübvansiyonu hem gelir hem ikame etkisi yaratır; nakit destek yalnızca gelir etkisi yarattığı için o mala yönelim daha zayıftır.'),
  ('Bir mesajlaşma uygulamasının yeni bir kullanıcı katıldıkça mevcut kullanıcılar için de daha değerli hâle gelmesi talep eğrisinin hangi varsayımını zayıflatır?', 'Bireysel taleplerin birbirinden bağımsız olduğu varsayımını', ['Talebin fiyatla ters yönde değiştiği varsayımını', 'Tüketicinin gelirinin ve bütçesinin sınırlı olduğu varsayımını', 'Malların bölünebilir olduğu varsayımını'], 'Standart piyasa talebi bireysel talepler bağımsızken yatay toplanarak elde edilir; ağ dışsallığında bireysel talep başkalarının alımına bağlıdır.'),
  ('Q = 5·K^0,5·L^0,5 üretim fonksiyonunda sermaye kısa dönemde 16 birimde sabittir. Firma 25 işçi çalıştırırken emeğin marjinal ürünü kaçtır?', '2', ['10', '4', '20,0'], 'Q = 20√L olur; MPL = 10/√L = 10/5 = 2.'),
  ('Q = K^0,3 · L^0,5 üretim fonksiyonuna sahip bir firma bütün girdileri iki katına çıkarırsa çıktı yaklaşık kaç katına çıkar?', '1,74', ['2,00', '1,600', '1,41'], '2^(0,3+0,5) = 2^0,8 ≈ 1,74; çıktı girdilerden daha az arttığı için ölçeğe göre azalan getiri vardır.'),
  ('Q = K + L + K·L üretim fonksiyonunda girdiler iki katına çıkarıldığında hangi tür ölçek getirisi görülür?', 'Artan', ['Sabit', 'Azalan', 'Önce azalan sonra sabit'], 'Yeni çıktı 2K + 2L + 4KL olur; bu, önceki çıktının iki katı olan 2K + 2L + 2KL\'den büyüktür.'),
  ('Bir firma ölçeğe göre sabit getiriyle üretim yapıyor ve girdi fiyatları firmanın büyüklüğünden etkilenmiyor. Firmanın uzun dönem ortalama maliyeti üretim arttıkça nasıl değişir?', 'Sabit kalır.', ['Sürekli düşer.', 'Sürekli artar.', 'Önce düşer sonra artar.'], 'Girdiler ve çıktı aynı oranda arttığından birim maliyet değişmez; uzun dönem ortalama maliyet eğrisi yataydır.'),
  ('Bir fabrikanın bütün girdileri iki katına çıktığında, örneğin aynı fabrikadan bir tane daha kurulduğunda, çıktının da en az iki katına çıkması gerektiğini söyleyen gerekçeye ne ad verilir?', 'Çoğaltma (replikasyon) argümanı', ['Azalan verimler kanunu', 'Say yasası', 'Engel yasası'], 'Bir tesisin aynısı kurulabiliyorsa çıktının en az iki katına çıkması beklenir; bu yüzden ölçeğe göre azalan getiri çoğu zaman gizli bir sabit girdiye bağlanır.'),
  ('Q = K^0,25 · L^0,75 üretim fonksiyonunda firma eşit miktarda emek ve sermaye kullanıyorsa teknik ikame oranı (MPL/MPK) kaçtır?', '3', ['1/3', '1', '0,75'], 'MRTS = (0,75/0,25) · (K/L) = 3 × 1 = 3.'),
  ('Leontief (sabit oranlı) ve doğrusal üretim fonksiyonlarının ikame esneklikleri sırasıyla nedir?', '0 ve sonsuz', ['Sonsuz ve 0', '1 ve 0', '0 ve 1'], 'Leontief\'te girdi oranı hiç değişmez (σ = 0); doğrusal fonksiyonda ise MRTS hiç değişmeden oran sınırsız değişebilir (σ = ∞).'),
  ('Rekabetçi piyasalarda ölçeğe göre sabit getirili Q = K^0,3 · L^0,7 üretim fonksiyonu kullanılan bir ekonomide toplam gelirden emeğe giden pay yaklaşık yüzde kaçtır?', '70', ['30', '50', '100'], 'Girdiler marjinal ürünleri kadar ödendiğinde wL/Q = β = 0,7 olur; emeğin payı %70\'tir.'),
  ('Bir atölyede 1\'den 6\'ya kadar işçiyle toplam üretim sırasıyla 10, 24, 39, 48, 50 ve 48 birimdir. Üçüncü üretim evresi kaçıncı işçiyle başlar?', '6. işçi', ['5. işçi', '4. işçi', 'Üçüncü evre oluşmaz'], '6. işçinin marjinal ürünü 48 − 50 = −2\'dir; marjinal ürün negatife döndüğünde üçüncü evre başlar.'),
  ('Aynı atölyede (1\'den 6\'ya kadar işçiyle toplam üretim 10, 24, 39, 48, 50, 48) emeğin ortalama ürünü kaçıncı işçide en yüksektir?', '3. işçi', ['2. işçi', '4. işçi', 'Ortalama ürün sürekli artar'], 'Ortalama ürünler 10, 12, 13, 12, 10 ve 8\'dir; en yüksek değer 3. işçide (13) görülür.'),
  ('Toplam ürün eğrisinin dönüm (büküm) noktası hangi büyüklüğün en yüksek olduğu yere karşılık gelir?', 'Marjinal ürünün', ['Ortalama ürünün', 'Toplam ürünün', 'Ortalama sabit maliyetin'], 'Dönüm noktasında toplam ürün artan hızla artmayı bırakıp azalan hızla artmaya başlar; bu nokta marjinal ürünün zirvesidir.'),
  ('Bir firmada emeğin marjinal ürünü 20, ücret 100 TL; sermayenin marjinal ürünü 30, sermayenin kirası 100 TL\'dir. Aynı çıktıyı daha ucuza üretmek için firma ne yapmalıdır?', 'Sermayeyi artırıp emeği azaltmalıdır.', ['Emeği artırıp sermayeyi azaltmalıdır.', 'Girdi bileşimini değiştirmemelidir.', 'Her iki girdiyi de aynı oranda azaltmalıdır.'], 'Sermayeye harcanan lira 0,3, emeğe harcanan lira 0,2 birim çıktı getiriyor; sermaye lehine kaymak maliyeti düşürür.'),
  ('Aynı firma (Q = K^0,5 · L^0,5, w = 4 TL, r = 1 TL) 20 birim çıktıyı en düşük maliyetle üretirse toplam maliyet kaç TL olur?', '80', ['100', '50', '40'], 'K = 4L iken Q = 2L = 20 olduğundan L = 10, K = 40; maliyet 4 × 10 + 1 × 40 = 80 TL.'),
  ('Belirli bir çıktıyı en düşük maliyetle üretmek için gereken girdi miktarlarını çıktıya ve girdi fiyatlarına bağlayan fonksiyonlara ne ad verilir?', 'Koşullu girdi talepleri', ['Marshall talepleri', 'Piyasa arz fonksiyonları', 'Üretim imkânları eğrileri'], 'Koşullu (Hicks tipi) girdi talepleri çıktı düzeyi sabitken girdi fiyatlarına tepkiyi gösterir; ürünün fiyatına bağlı değildir.'),
  ('Çıktı düzeyi sabitken ücret artarsa maliyetini en aza indiren firmanın koşullu emek talebi nasıl değişir?', 'Azalır ya da değişmez; asla artmaz.', ['Her zaman artar.', 'Ücretle aynı oranda artar; çünkü çıktı sabittir.', 'Önce artar sonra azalır.'], 'Aynı eş ürün eğrisi üzerinde göreli olarak pahalanan girdiden ucuz olana kayılır; bu ikame etkisi negatiftir.'),
  ('Maliyet fonksiyonunun ücrete göre türevinin koşullu emek talebini verdiğini söyleyen sonuç hangisidir?', 'Shephard lemması', ['Hotelling lemması', 'Roy özdeşliği', 'Euler teoremi'], 'Üretim kuramında Shephard lemması ∂C(w, r, Q)/∂w = L(w, r, Q) biçimindedir.'),
  ('Homotetik bir üretim fonksiyonunda girdi fiyatları sabitken genişleme yolu nasıldır?', 'Orijinden çıkan bir doğrudur.', ['Yatay bir doğrudur.', 'Geriye doğru bükülen bir eğridir.', 'Dikey bir doğrudur.'], 'Homotetik teknolojide MRTS yalnızca K/L oranına bağlıdır; aynı fiyat oranında aynı K/L seçildiği için yol orijinden geçen bir ışındır.'),
  ('Bir firmanın çıktısı arttıkça kullandığı vasıfsız emek miktarının azalması, bu girdinin hangi tür girdi olduğunu gösterir?', 'Düşük (inferior) girdi', ['Normal girdi', 'Sabit girdi', 'Tamamlayıcı (bağımlı) girdi'], 'Çıktı artarken kullanımı azalan girdiye düşük girdi denir; büyüyen firmalar daha otomatik teknolojilere geçerken görülebilir.'),
  ('Q = K + 2L üretim fonksiyonuna sahip bir firmada ücret 5 TL, sermayenin kirası 3 TL\'dir. Firma maliyeti en aza indirmek için ne yapar?', 'Yalnızca emek kullanır.', ['Yalnızca sermaye kullanır.', 'İki girdiyi eşit kullanır.', 'Emek ve sermayeyi 2\'ye 1 oranında kullanır.'], 'Emek bir birim çıktıyı 5/2 = 2,5 TL\'ye, sermaye 3 TL\'ye üretir; tam ikamelerde ucuz olan girdiyle köşe çözümü seçilir.'),
  ('Ölçeğe göre sabit getiri altında üretim yapan bir firmanın toplam maliyet fonksiyonu çıktıya göre nasıldır (girdi fiyatları sabitken)?', 'Doğrusaldır; maliyet çıktıyla aynı oranda artar.', ['Çıktının karesiyle artar; marjinal maliyet yükselir.', 'Çıktıdan bağımsızdır.', 'Çıktı arttıkça azalır.'], 'Girdiler çıktıyla orantılı arttığından maliyet de orantılı artar; ortalama ve marjinal maliyet sabittir ve birbirine eşittir.'),
  ('Q = K^0,25 · L^0,25 üretim fonksiyonuna sahip bir firmada girdi fiyatları sabitse en düşük toplam maliyet çıktıya nasıl bağlıdır?', 'Çıktının karesiyle orantılıdır.', ['Çıktıyla doğru orantılıdır.', 'Çıktının kareköküyle orantılıdır.', 'Çıktıdan bağımsızdır.'], 'Üslerin toplamı 0,5\'tir; çıktıyı iki katına çıkarmak için girdilerin dört katına çıkması gerekir. Bu yüzden maliyet Q²\'yle orantılıdır.'),
  ('Maliyetin çıktı esnekliği 0,8 olan bir firmada (yani çıktı %10 artarken maliyet %8 artıyorsa) hangisi doğrudur?', 'Ortalama maliyet düşmektedir; ölçek ekonomisi vardır.', ['Ortalama maliyet artmaktadır; ölçek eksi ekonomisi vardır.', 'Marjinal maliyet ortalama maliyetten büyüktür.', 'Firma ölçeğe göre azalan getiri altındadır.'], 'Maliyet esnekliği MC/AC\'ye eşittir; 1\'den küçükse MC < AC olur ve ortalama maliyet düşer.'),
  ('Eş maliyet doğrusu ile eş ürün eğrisinin teğet olmadığı, ancak eş ürün eğrisini kestiği bir noktada üretim yapan firma için ne söylenebilir?', 'Aynı çıktıyı daha düşük maliyetle üretebilir.', ['Maliyetini en aza indirmiştir.', 'Mevcut bütçesiyle bu çıktı düzeyini hiçbir biçimde üretemez.', 'Ölçeğe göre artan getiri altındadır.'], 'Kesişme noktasında MRTS ≠ w/r\'dir; girdi bileşimi değiştirilerek aynı eş ürün eğrisinde daha alçak bir eş maliyet doğrusuna inilebilir.'),
  ('Ortalama sabit maliyet eğrisi geometrik olarak hangi biçimdedir?', 'Dik açılı (dikdörtgen) hiperbol', ['U biçimli ve en düşük noktası olan bir eğri', 'Pozitif eğimli doğru', 'Yatay doğru'], 'AFC × Q = TFC sabit olduğundan eğri, altındaki her dikdörtgenin alanı aynı olan bir hiperboldür.'),
  ('Uzun dönem ortalama maliyet eğrisi neden hiçbir zaman bir kısa dönem ortalama maliyet eğrisinin üzerinde bulunmaz?', 'Uzun dönemde bütün girdiler ayarlanabildiği için en ucuz tesis büyüklüğü seçilebilir.', ['Uzun dönemde girdi fiyatları düşer.', 'Uzun dönemde sabit maliyetler iki katına çıkar.', 'Uzun dönemde teknoloji her zaman ilerler ve bütün tesisler yenilenerek ucuzlar.'], 'Kısa dönemde tesis büyüklüğü sabittir; uzun dönemde her çıktı için en uygun tesis seçildiğinden maliyet en fazla kısa dönemdeki kadar olur.'),
  ('Bir kısa dönem ortalama maliyet eğrisinin uzun dönem ortalama maliyet eğrisine teğet olduğu çıktı düzeyinde marjinal maliyetler için ne söylenir?', 'Kısa ve uzun dönem marjinal maliyetleri eşittir.', ['Kısa dönem marjinal maliyeti her zaman daha düşüktür.', 'Uzun dönem marjinal maliyeti sıfırdır.', 'İki marjinal maliyet arasında ilişki yoktur.'], 'Teğet noktasında iki toplam maliyet eğrisi de birbirine değer ve aynı eğime sahiptir; eğim marjinal maliyettir.'),
  ('Tek bir firmada iki ürün ayrı ayrı üretilirse 60 ve 50 milyon TL, birlikte üretilirse toplam 88 milyon TL tutuyor. Kapsam ekonomisinin derecesi (ayrı maliyet toplamı ile ortak maliyetin farkının ortak maliyete oranı) kaçtır?', '0,25', ['0,20', '0,220', '1,25'], '(60 + 50 − 88) / 88 = 22 / 88 = 0,25. Pozitif değer kapsam ekonomisi olduğunu gösterir.'),
  ('Öğrenme eğrisi etkisini ölçek ekonomisinden ayıran temel özellik hangisidir?', 'Birim maliyetin birikimli toplam üretimle düşmesi', ['Birim maliyetin dönem başına üretim hızıyla düşmesi', 'Birim maliyetin girdi fiyatlarıyla düşmesi', 'Birim maliyetin hiç değişmemesi'], 'Öğrenme, geçmişte üretilen toplam miktara bağlıdır; ölçek ekonomisi ise belirli bir dönemdeki üretim ölçeğine bağlıdır.'),
  ('Bir mağazanın açık kaldığı sürece ödediği ısınma gideri üretim miktarına bağlı değildir ama mağaza tamamen kapanırsa ortadan kalkar. Bu tür maliyete ne ad verilir?', 'Yarı sabit maliyet', ['Batık (geri alınamaz) maliyet', 'Değişken maliyet', 'Marjinal maliyet'], 'Yarı sabit maliyetler çıktı düzeyinden bağımsızdır ancak çıktı sıfıra inince kaçınılabilir; batık maliyet ise hiçbir koşulda geri alınamaz.'),
  ('Bir kafe sahibi \'fırının parasını zaten ödedik, ekmek pişirmek bize neredeyse bedava\' diyor. Ancak aynı fırın kiraya verilse ayda 5.000 TL getirecektir. Bu değerlendirmedeki hata hangisidir?', 'Fırını kullanmanın fırsat maliyeti göz ardı edilmiştir.', ['Fırının satın alma bedeli değişken maliyet sayılmalıdır.', 'Fırın bir batık maliyet olduğu için kira geliri hesaba katılmaz.', 'Ekmek üretiminin marjinal maliyeti her zaman sıfırdır.'], 'Satın alma bedeli batık olsa da fırını kullanmak, onu kiraya vermekten vazgeçmek demektir; bu 5.000 TL\'lik örtük maliyet hesaba katılmalıdır.'),
  ('Ürününü 10 TL\'den satan bir firmada 1., 2., 3. ve 4. işçinin marjinal ürünleri sırasıyla 30, 25, 18 ve 9 birimdir. Günlük ücret 150 TL ise kârını en yüksek yapan firma kaç işçi çalıştırır?', '3 işçi', ['2 işçi', '4 işçi', 'Hiç işçi çalıştırmaz'], 'Marjinal ürün değerleri 300, 250, 180 ve 90 TL\'dir. Üçüncü işçi ücretten (150) fazla, dördüncü işçi ücretten az katkı yapar.'),
  ('Hicks-Marshall türev talep yasalarına göre aşağıdakilerden hangisi bir sektördeki emek talebini daha esnek hâle getirir?', 'Emeğin yerine kolayca başka girdilerin kullanılabilmesi', ['Emek maliyetinin firmanın toplam maliyeti içinde çok küçük bir pay tutması', 'Ürünün talebinin inelastik olması', 'Diğer girdilerin arzının tamamen inelastik olması'], 'İkame kolaylığı, ürün talebinin esnekliği, emeğin maliyet payı ve diğer girdilerin arz esnekliği arttıkça emek talebi de esnekleşir.'),
  ('Bir teknolojik yenilik verili bir K/L oranında sermayenin marjinal ürününü emeğinkinden daha çok artırıyorsa bu yenilik nasıl adlandırılır?', 'Emek tasarruf eden (sermaye kullanan)', ['Sermaye tasarruf eden (emek kullanan)', 'Hicks-nötr', 'Ölçeğe göre azalan getiri (verim kaybı)'], 'Sermayenin göreli verimini artıran yenilik firmaları aynı fiyatlarda daha sermaye yoğun üretime yöneltir, yani emekten tasarruf ettirir.'),
  ('Teknik olarak etkin olduğu hâlde ekonomik olarak etkin olmayan bir firma için en uygun açıklama hangisidir?', 'Eş ürün eğrisi üzerinde ama girdi fiyatlarına göre yanlış bileşimi kullanıyordur.', ['Eş ürün eğrisinin altında, yani üretim sınırının içinde üretim yapıyordur.', 'Girdilerinin bir kısmını hiç kullanmıyordur.', 'Ürününü maliyetinin altında satıyordur.'], 'Ekonomik etkinlik teknik etkinliğin yanında maliyeti en aza indiren girdi bileşiminin seçilmesini, yani MRTS = w/r koşulunu da gerektirir.'),
  ('Harvey Leibenstein\'in 1966\'da ortaya attığı, rekabet baskısı zayıf olan firmaların teknik olarak ulaşılabilecek en düşük maliyetin üzerinde üretim yapmasını anlatan kavram hangisidir?', 'X-etkinsizliği', ['Ölçek eksi ekonomisi', 'Tahsis etkinsizliği', 'Pareto etkinsizliği'], 'Leibenstein\'a göre motivasyon eksikliği ve örgütsel gevşeklik firmaları üretim sınırının içinde tutar.'),
  ('William Baumol\'un 1959\'da önerdiği firma modeline göre yöneticiler kâr yerine hangi büyüklüğü en çoklaştırmaya çalışır?', 'Belirli bir asgari kâr kısıtı altında satış hasılatını', ['Firmanın toplam maliyetini ve tedarikçilerinin kârını', 'Çalışan sayısını sınırsız olarak', 'Hisse senedi fiyatını her ne pahasına olursa olsun'], 'Baumol\'e göre yöneticilerin ücreti ve prestiji satışlarla ilişkili olduğundan, hissedarları tatmin edecek bir kâr düzeyinin üzerinde satışlar artırılır.'),
  ('Satış hasılatını en çoklaştıran bir firma, kârı en çoklaştıran bir firmaya göre genellikle nasıl davranır (talep eğrisi negatif eğimliyken)?', 'Daha çok üretir ve daha düşük fiyat koyar.', ['Daha az üretir ve daha yüksek fiyat koyar.', 'Aynı miktarı aynı fiyattan satar.', 'Hiç üretim yapmaz; çünkü kâr sıfıra iner.'], 'Hasılat MR = 0\'da, kâr MR = MC\'de en yüksektir. MC pozitif olduğundan hasılat maksimizasyonu daha büyük bir çıktıyı gerektirir.'),
  ('Adolf Berle ve Gardiner Means\'in 1932\'de dikkat çektiği, büyük anonim şirketlerde yöneticilerin hissedarlardan farklı amaçlar izleyebilmesine yol açan olgu hangisidir?', 'Mülkiyet ile yönetimin (kontrolün) ayrılması', ['Ölçeğe göre azalan getiri', 'Kapsam ekonomisi', 'Fiyat yapışkanlığı ve menü maliyetleri'], 'Hisseler çok sayıda küçük ortağa dağıldığında yönetimin denetimi zayıflar; bu da kâr dışı amaçların izlenmesine imkân verir.'),
  ('Qd = 120 − 4P ve Qs = 2P olan piyasada satıcılardan birim başına 6 TL vergi alınırsa tüketicilerin ödediği yeni fiyat kaç TL olur?', '22', ['26', '20', '24,5'], 'Satıcının eline geçen fiyat P − 6\'dır: 120 − 4P = 2(P − 6) ⇒ 6P = 132 ⇒ P = 22 TL. Satıcıya 16 TL kalır.'),
  ('Aynı vergili piyasada (Qd = 120 − 4P, Qs = 2P, birim vergi 6 TL) devletin toplam vergi geliri ve ölü ağırlık kaybı nedir?', '192 TL ve 24 TL', ['216 TL ve 12 TL', '240 TL ve 24 TL', '192 TL ve 48,0 TL'], 'Vergili miktar 120 − 4 × 22 = 32 birimdir. Vergi geliri 6 × 32 = 192 TL, ölü ağırlık kaybı ½ × 6 × (40 − 32) = 24 TL\'dir.'),
  ('Arz esnekliği 1,5, talep esnekliği (mutlak değer) 0,5 olan bir malda küçük bir birim vergisinin yükünün yaklaşık ne kadarı tüketicilere düşer?', '%75', ['%25', '%50', '%33,3'], 'Tüketicinin payı Es / (Es + |Ed|) = 1,5 / 2 = 0,75\'tir.'),
  ('Birim başına sabit tutarlı vergi yerine fiyatın belli bir yüzdesi olarak alınan (değer üzerinden) vergi arz eğrisini nasıl etkiler?', 'Eğriyi yukarı doğru döndürür; fiyat yükseldikçe vergi tutarı büyür.', ['Eğriyi her noktada aynı tutar kadar yukarı paralel kaydırır.', 'Arz eğrisini etkilemez, yalnızca talep eğrisini aşağı doğru kaydırır.', 'Eğriyi aşağı doğru kaydırır.'], 'Değer üzerinden vergide birim başına vergi fiyatla artar; bu yüzden kayma yüksek fiyatlarda daha büyüktür.'),
  ('Bir vergi yasada alıcılardan toplanacak biçimde düzenlenirse, satıcılardan toplanmasına göre vergi yükünün dağılımı nasıl değişir?', 'Değişmez; yük esnekliklere göre aynı biçimde paylaşılır.', ['Yükün tamamı alıcılara geçer.', 'Yükün tamamı satıcılara geçer.', 'Yük her zaman alıcı ile satıcı arasında eşit olarak paylaşılır.'], 'Yasal yükümlülük ekonomik yükü belirlemez; hangi tarafın talep ya da arz eğrisi kaydırılırsa kaydırılsın sonuç aynıdır.'),
  ('Marshall tipi kararlılık analizinde neyin ayarlandığı varsayılır?', 'Talep fiyatı arz fiyatından yüksekse miktarın artırıldığı', ['Talep fazlası varsa fiyatın yükseltildiği', 'Gelirlerin fiyatlarla birlikte aynı oranda değiştiği ve dengeyi bozduğu', 'Bütün piyasaların aynı anda dengelendiği'], 'Marshall\'da üreticiler miktara göre karar verir; alıcıların ödemeye razı olduğu fiyat, üreticilerin istediği fiyatı aşıyorsa üretim artar.'),
  ('Örümcek ağı modelinde fiyat dalgalanmalarının zamanla sönümlenip dengeye yaklaşması için hangi koşul gerekir?', 'Arzın fiyata duyarlılığının talebinkinden düşük olması', ['Arzın fiyata duyarlılığının talebinkinden yüksek olması', 'Arz ve talebin eşit duyarlılıkta olması', 'Talebin tamamen inelastik olması'], 'Arz talebe göre daha az tepki verirse her dönemde fiyat sapması küçülür; tersi durumda dalgalanma büyüyerek patlar.'),
  ('Örümcek ağı modelinde arz ve talep eğrilerinin eğimleri mutlak değerce eşitse fiyat nasıl davranır?', 'Aynı genlikte sürekli dalgalanır.', ['Hızla dengeye yaklaşır.', 'Sınırsız büyüyerek patlar.', 'İlk dönemden sonra yeni bir düzeyde sabitlenir.'], 'Eğimler eşitse her dönemdeki sapma bir öncekiyle aynı büyüklükte kalır; dalgalanma ne söner ne büyür.'),
  ('Domuz eti piyasasında 19. yüzyıldan beri gözlenen ve örümcek ağı modelinin klasik örneği sayılan dalgalanmaya ne ad verilir?', 'Domuz döngüsü', ['Kondratiev dalgası', 'Juglar döngüsü', 'Kitchin döngüsü'], 'Domuz yetiştirmenin gecikmeli üretim süreci, fiyatlarda yıllar süren düzenli bir çevrime yol açar.'),
  ('Marshall\'ın zaman dönemleri sınıflamasında nüfus, teknoloji ve zevklerin de değişebildiği en uzun döneme ne ad verilir?', 'Seküler (çok uzun) dönem', ['Piyasa (anlık) dönemi', 'Kısa dönem', 'Uzun dönem'], 'Marshall dördüncü olarak, temel koşulların da değiştiği seküler dönemi tanımlamıştır.'),
  ('Talep kalıcı olarak arttığında, arzın zamanla daha esnek hâle gelmesi nedeniyle fiyatın seyri genellikle nasıl olur?', 'Önce sert yükselir, sonra kısmen geri iner.', ['Önce düşer, sonra yükselir.', 'Kalıcı olarak ilk tepkinin üzerinde kalır.', 'Hiç değişmez; çünkü arz anında uyum sağlar.'], 'Kısa dönemde arz inelastik olduğundan fiyat çok yükselir; zamanla üretim kapasitesi arttıkça fiyat kısmen geriler.'),
  ('İki kişilik bir mübadelede dağılımın Pareto etkin olması için hangi koşul sağlanmalıdır?', 'İki kişinin marjinal ikame oranlarının eşit olması', ['İki kişinin her iki maldan da tam olarak eşit miktarda mal tüketmesi', 'İki kişinin gelirlerinin eşit olması', 'Her iki malın fiyatının eşit olması'], 'MRS\'ler farklıysa her ikisinin de yararlanacağı bir takas yapılabilir; etkinlik bu fırsatın tükenmesini gerektirir.'),
  ('Ali bir elma için 2 portakal vermeye, Banu ise bir elma için yalnızca 1 portakal vermeye razıdır. Hangi takas ikisini de daha iyi duruma getirebilir?', 'Banu Ali\'ye elma verir, karşılığında 1 ile 2 arasında portakal alır.', ['Ali Banu\'ya elma verir, karşılığında 1 portakaldan az alır.', 'Ali Banu\'ya elma verir, karşılığında 2 portakaldan fazlasını almakta ısrar eder.', 'Hiçbir takas ikisini birden kazançlı çıkaramaz.'], 'Ali elmaya Banu\'dan daha çok değer biçer; elma Banu\'dan Ali\'ye, iki değerlemenin arasındaki bir oranla geçerse ikisi de kazanır.'),
  ('Refah iktisadının ikinci temel teoremi neyi ifade eder?', 'Uygun bir başlangıç dağılımı (götürü transferlerle) yapılırsa her Pareto etkin dağılıma piyasa yoluyla ulaşılabileceğini', ['Her piyasa dengesinin adil olduğunu', 'Devletin bütün fiyatları ve üretim miktarlarını merkezden belirlemesi gerektiğini ve piyasanın yetersizliğini', 'Pareto etkinliğin hiçbir zaman sağlanamayacağını'], 'İkinci teorem, etkinlik ile dağılımın ayrılabileceğini; bölüşüm hedeflerine fiyatları bozmadan transferlerle ulaşılabileceğini gösterir.'),
  ('Bir ekonomide iki malın üretim bileşiminin etkin olması için hangi eşitlik gerekir?', 'Marjinal dönüşüm oranı ile tüketicilerin marjinal ikame oranının eşitliği', ['Bütün malların ortalama maliyetlerinin piyasa fiyatlarına ve gelire eşitliği', 'İki malın üretim miktarlarının eşitliği', 'İki malın fiyatlarının eşitliği'], 'MRT, bir malın ötekisi cinsinden üretim maliyetini; MRS ise tüketicinin değerlemesini gösterir. Farklıysa üretim bileşimi değiştirilerek refah artırılabilir.'),
  ('Üretim imkânları eğrisinin eğimi olan marjinal dönüşüm oranı (X ekseninde X malı) hangi oranla gösterilebilir?', 'X\'in marjinal maliyetinin Y\'nin marjinal maliyetine oranı', ['X\'in fiyatının gelire oranı', 'X\'in ortalama ürününün Y\'ninkine oranı', 'X\'in marjinal faydasının fiyatına ve gelire oranı'], 'Bir birim X üretmek için kaynakları Y\'den çekmek gerekir; feda edilen Y miktarı MCx/MCy\'ye eşittir.'),
  ('Genel denge modellerinde \'n piyasadan n − 1\'i dengedeyse sonuncusu da dengededir\' sonucu hangi ilkeye dayanır?', 'Walras yasası', ['Say yasası', 'Gresham yasası', 'Engel yasası'], 'Her ajanın bütçe kısıtı nedeniyle bütün piyasalardaki fazla taleplerin değer toplamı sıfırdır; bu yüzden bir piyasa bağımsız değildir.'),
  ('Genel denge modellerinde yalnızca göreli fiyatlar belirlenebildiği için bir malın fiyatının 1 kabul edilip ötekilerin onun cinsinden ölçülmesine ne ad verilir?', 'Numeraire (hesap birimi) seçimi', ['Fiyat tavanı', 'Para yanılsaması', 'Fiyat endekslemesi ve bazlama'], 'Talep sıfırıncı dereceden homojen olduğu için bütün fiyatlar ancak bir ölçek dâhilinde belirlenir; bir mal numeraire seçilir.'),
  ('Kısa dönemde sabit bir üretim faktörüne (örneğin bir makineye) yapılan ve toplam hasılat ile değişken maliyet arasındaki farka eşit olan getiriye Marshall\'ın verdiği ad nedir?', 'Yarı rant', ['Ekonomik kâr', 'Tüketici rantı', 'Mutlak (Ricardo) rantı'], 'Yarı rant kısa dönemde sabit faktörün getirisidir; uzun dönemde faktör arzı ayarlandıkça ortadan kalkabilir.'),
  ('Bir üretim faktörünün kazancının, o faktörü mevcut kullanımında tutmak için gereken en düşük ödemeyi (transfer kazancını) aşan kısmına ne ad verilir?', 'Ekonomik rant', ['Muhasebe kârı', 'Fırsat maliyeti', 'Yarı sabit maliyet'], 'Ekonomik rant transfer kazancının üzerindeki fazladır; arzı inelastik olan faktörlerde kazancın büyük kısmı rant niteliğindedir.'),
  ('Ölçeğe göre sabit getirili bir üretim fonksiyonunda her faktöre marjinal ürünü kadar ödeme yapılırsa toplam ödemeler toplam çıktıya eşit olur. Bu sonuç hangi matematiksel teoreme dayanır?', 'Euler\'in homojen fonksiyonlar teoremi', ['Pisagor teoremi', 'Bayes teoremi', 'Merkezî limit teoremi ve büyük sayılar'], 'Birinci dereceden homojen F için K·FK + L·FL = F olur; bu \'ürünün tükenmesi\' sorunu Wicksteed ve Wicksell tarafından tartışıldı.'),
  ('Ünlü bir şarkıcı müzik yapmasaydı başka bir işte yılda 400.000 TL kazanabilecekken müzikten yılda 10 milyon TL kazanıyor. Kazancının ne kadarı ekonomik ranttır?', '9,6 milyon TL', ['10,0 milyon TL', '400.000 TL', '5,2 milyon TL'], 'Ekonomik rant kazancın transfer kazancını aşan kısmıdır: 10.000.000 − 400.000 = 9.600.000 TL.'),
  ('Koyun yetiştiren bir çiftliğin aynı süreçte hem et hem yün elde etmesi gibi birinin üretimi ötekini kendiliğinden doğuran ürünlere ne ad verilir?', 'Ortak (birleşik) ürünler', ['Tamamlayıcı mallar', 'Kamusal (dışlanamaz) mallar', 'Düşük mallar'], 'Marshall\'ın ortak arz örneğinde yün talebindeki artış, et arzını da artırarak et fiyatını düşürebilir.'),
  ('İki ayrı fabrikası olan bir firma belirli bir toplam üretimi en düşük maliyetle gerçekleştirmek için üretimi fabrikalar arasında nasıl bölmelidir?', 'Fabrikaların marjinal maliyetleri eşitlenecek biçimde', ['Fabrikaların ortalama maliyetleri eşitlenecek biçimde', 'Üretimi iki fabrika arasında eşit bölerek', 'Tüm üretimi ortalama maliyeti düşük olan fabrikaya vererek'], 'Marjinal maliyetler farklıysa üretimi pahalı fabrikadan ucuz olana kaydırmak toplam maliyeti düşürür; bu, MC\'ler eşitlenene kadar sürer.'),
  ('A fabrikasının marjinal maliyeti MCA = 2qA, B fabrikasınınki MCB = 3qB\'dir. Firma toplam 50 birimi en ucuza üretmek isterse A fabrikasında kaç birim üretmelidir?', '30', ['20', '25', '33,3'], '2qA = 3qB ve qA + qB = 50 ⇒ qA = 1,5qB, 2,5qB = 50 ⇒ qB = 20, qA = 30.'),
  ('Stone-Geary fayda fonksiyonundan türetilen ve tüketicinin önce her maldan \'zorunlu\' bir miktar aldığını varsayan talep sistemine ne ad verilir?', 'Doğrusal harcama sistemi', ['Neredeyse ideal talep sistemi', 'Cobb-Douglas talep sistemi', 'Rotterdam modeli'], 'Richard Stone 1954\'te doğrusal harcama sistemini İngiltere verilerine uyguladı; harcamalar gelir ve fiyatlarla doğrusal ilişkilidir.'),
  ('Her Giffen malı ile her düşük mal arasındaki ilişki için hangisi doğrudur?', 'Her Giffen malı düşük maldır, ama her düşük mal Giffen malı değildir.', ['Her düşük mal Giffen malıdır.', 'Giffen malları normal mallardır.', 'İki kavram arasında hiçbir ilişki yoktur; biri gelirle, öteki fiyatla ilgilidir.'], 'Giffen olabilmek için gelir etkisinin ters yönde olması (düşük mal) ve ikame etkisini aşması gerekir; çoğu düşük malda gelir etkisi yetersiz kalır.'),
  ('Talep esnekliği kavramını 1890\'da \'Principles of Economics\' adlı eseriyle iktisada yerleştiren iktisatçı kimdir?', 'Alfred Marshall', ['Adam Smith', 'David Ricardo', 'John Stuart Mill'], 'Marshall fiyat esnekliğini tanımladı ve talebin fiyata duyarlılığını ölçmenin yollarını gösterdi.'),
  ('Ekonomik analizin matematiksel temellerini ortaya koyan, açıklanmış tercih ve karşılaştırmalı durağanlık yöntemini sistemleştiren 1947 tarihli \'Foundations of Economic Analysis\' kimindir?', 'Paul Samuelson', ['Milton Friedman', 'Kenneth Arrow', 'John von Neumann'], 'Samuelson\'ın doktora tezine dayanan bu eser, optimizasyon ve kararlılık analizini iktisadın ortak dili hâline getirdi.'),
  ('Milton Friedman ve Leonard Savage\'ın 1948\'de önerdiği, önce içbükey sonra dışbükey sonra yine içbükey kısımları olan fayda eğrisi neyi açıklamak için geliştirilmiştir?', 'Aynı kişilerin hem sigorta yaptırıp hem piyango bileti almasını', ['İnsanların neden tasarruf ettiğini', 'Talep eğrisinin neden negatif eğimli olduğunu ve fiyatla ilişkisini', 'Ücret artışının çalışma saatlerine etkisini'], 'Eğrinin içbükey kısmı kayıplara karşı sigortayı, dışbükey kısmı büyük kazanç umuduyla kumarı açıklar.'),
  ('A piyangosu %50 olasılıkla 100 TL, %50 olasılıkla 200 TL veriyor. B piyangosu %50 olasılıkla 100 TL, %50 olasılıkla 150 TL veriyor. Daha çok parayı daha aza tercih eden herkes için hangisi doğrudur?', 'A, B\'ye tercih edilir; A birinci dereceden stokastik baskındır.', ['B, A\'ya tercih edilir; çünkü daha az risklidir.', 'Seçim kişinin risk tutumuna bağlıdır; riskten kaçınan B\'yi seçer.', 'İki piyango eşdeğerdir.'], 'Her durumda A\'nın ödemesi B\'ninkine eşit ya da büyüktür; bu yüzden risk tutumundan bağımsız olarak A seçilir.'),
  ('Beklenen değeri değiştirmeden bir piyangonun sonuçlarını ortalamadan daha uzağa yaymaya (ortalamayı koruyan yayılma) riskten kaçınan bir kişi nasıl tepki verir?', 'Yeni piyangoyu eskisinden daha kötü bulur.', ['Yeni piyangoyu eskisinden daha iyi bulur.', 'İki piyangoya kayıtsız kalır.', 'Yeni piyangoyu ancak beklenen değeri düşükse seçer.'], 'Beklenen değer aynıyken yayılma yalnızca riski artırır; içbükey faydaya sahip kişi için beklenen fayda düşer.'),
  ('Sigorta primleri beklenen kaybın üzerinde (aktüeryal olarak adil olmayan) belirlenmişse riskten kaçınan bir tüketicinin en iyi seçimi genellikle hangisidir?', 'Kaybın bir kısmını sigortalatıp bir kısmını kendisi üstlenmek', ['Kaybın tamamından fazlasını sigortalatmak', 'Her durumda ve her prim düzeyinde kaybın tamamını sigortalatmak', 'Kesinlikle hiç sigorta yaptırmamak'], 'Mossin\'in 1968\'de gösterdiği gibi primde yükleme varsa kısmi sigorta (örneğin muafiyetli poliçe) en iyisidir.'),
  ('Riskten kaçınan bir kişi beklenen değeri negatif olan bir kumara ne zaman katılır?', 'Hiçbir zaman; böyle bir kumar beklenen faydasını düşürür.', ['Kumarın olasılıkları eşitse her zaman', 'Serveti yeterince büyükse her zaman', 'Kumarın ödülü olası kayıptan büyükse her zaman katılır.'], 'Beklenen değeri negatif olan bir kumar, riskten kaçınan biri için beklenen değeri sıfır olan kumardan bile kötüdür; içbükey faydada asla kabul edilmez.'),
  ('George Stigler\'ın 1961\'de geliştirdiği bilgi ekonomisine göre bir tüketici en ucuz satıcıyı aramayı ne zaman bırakır?', 'Bir arama daha yapmanın beklenen kazancı maliyetine eşitlendiğinde', ['Bütün satıcıları tek tek dolaşıp fiyatlarını öğrendiğinde', 'İlk satıcıyı bulduğunda', 'Fiyatlar eşitlendiğinde'], 'Arama maliyetli olduğu için tüketiciler bilgiyi de marjinal kurala göre toplar; bu da aynı mal için fiyat dağılımının sürmesine izin verir.'),
  ('Homotetik tercihlere sahip bir tüketicinin geliri iki katına çıkarsa (fiyatlar sabitken) bütçe payları nasıl değişir?', 'Değişmez; her mala yapılan harcama iki katına çıkar.', ['Zorunlu malların payı artar, lüks malların payı azalır.', 'Bütün payların toplamı iki katına çıkar.', 'Yalnızca en ucuz malın payı artar.'], 'Homotetik tercihlerde bütün malların gelir esnekliği 1\'dir; tüketim sepeti orantılı büyür ve paylar sabit kalır.'),
  ('Bir malın fiyatı 10 TL\'den 12 TL\'ye çıkınca arz edilen miktar 100\'den 130\'a yükseliyor. Orta nokta yöntemiyle arz esnekliği yaklaşık kaçtır?', '1,43', ['1,50', '0,70', '1,250'], 'Miktar değişimi 30/115 ≈ %26,1, fiyat değişimi 2/11 ≈ %18,2\'dir; oranları ≈ 1,43.'),
  ('Orijinden geçen doğrusal bir arz eğrisi (Qs = cP) üzerinde arzın fiyat esnekliği için hangisi doğrudur?', 'Her noktada 1\'dir.', ['Fiyat arttıkça artar.', 'Fiyat arttıkça azalır.', 'Her noktada sıfırdır.'], 'Qs = cP için (dQ/dP)·(P/Q) = c · P/(cP) = 1 olur; eğimden bağımsız olarak esneklik birdir.'),
  ('Aşağıdaki mallardan hangisinin arzı kısa dönemde fiyat değişimlerine en az duyarlıdır?', 'Taze çilek', ['Plastik şişe', 'Konserve fasulye', 'Ofis kâğıdı'], 'Taze çilek bozulabildiği ve üretimi hasat zamanına bağlı olduğu için stoklanamaz; arzı kısa dönemde hızla artırılamaz.'),
  ('Sigara talebinin fiyat esnekliği −0,25 kabul edilirse sigara tüketimini %10 azaltmak için fiyatın yaklaşık yüzde kaç artırılması gerekir?', '40', ['10', '25', '2,5'], 'Gerekli fiyat değişimi = −10 / −0,25 = %40.'),
  ('Talep fonksiyonu Q = 1.000 / P biçiminde olan bir malda fiyat ne olursa olsun tüketicilerin bu mala yaptığı harcama hakkında ne söylenebilir?', 'Her fiyatta 1.000 TL\'dir.', ['Fiyat yükseldikçe artar.', 'Fiyat yükseldikçe azalır.', 'Fiyat 1.000 TL olduğunda sıfırdır.'], 'P · Q = 1.000 sabittir; bu talep eğrisi her noktada birim esnek olan dikdörtgen hiperboldür.'),
  ('Bir hanenin geliri 10.000 TL\'den 12.000 TL\'ye çıkınca peynir alımı 10 kilogramdan 12 kilograma çıkmıştır. Orta nokta yöntemiyle peynirin gelir esnekliği kaçtır?', '1', ['0,5', '2', '1,2'], 'Miktar değişimi 2/11, gelir değişimi 2.000/11.000 = 2/11\'dir; oranları 1\'dir.'),
  ('Q = 300 − 5P talep fonksiyonunda fiyat 40 TL iken nokta esnekliği kaçtır ve talep bu noktada nasıl nitelenir?', '−2; esnek', ['−0,5; inelastik', '−1; birim esnek', '−5; tam esnek'], 'Q = 300 − 200 = 100; ε = −5 × 40/100 = −2. Mutlak değer 1\'den büyük olduğu için talep esnektir.'),
  ('Bir malın talebinin fiyat esnekliği −0,6, gelir esnekliği 1,2\'dir. Fiyat %5, gelir %5 aynı anda artarsa talep edilen miktar yaklaşık ne kadar değişir?', '%3 artar.', ['%3 azalır.', '%9 artar.', 'Değişmez.'], 'Etkiler toplanır: −0,6 × 5 + 1,2 × 5 = −3 + 6 = +%3.'),
  ('Esneklik yerine talep eğrisinin eğimini kullanmanın sakıncası hangisidir?', 'Eğim ölçü birimlerine bağlıdır; esneklik birimsizdir.', ['Eğim her zaman pozitiftir.', 'Eğim yalnızca doğrusal talepte tanımlıdır.', 'Eğim fiyattan bağımsız değildir ve her noktada değişir.'], 'Miktar kilogramdan tona çevrilince eğim değişir; esneklik ise yüzde değişimlerin oranı olduğundan birimden etkilenmez.'),
  ('Talep esnekliği −2 ve arz esnekliği 1 olan bir piyasada talep kalıcı olarak %6 artarsa (her fiyatta), yeni dengede fiyat yaklaşık yüzde kaç değişir?', '%2 artar.', ['%6 artar.', '%3 artar.', '%2 azalır.'], 'Fiyattaki değişim ≈ talep kayması / (arz esnekliği − talep esnekliği) = 6 / (1 + 2) = %2.'),
  ('Q = K·L teknolojisiyle 16 birim üretmek isteyen bir firma üç bileşimi değerlendiriyor: (K = 2, L = 8), (K = 4, L = 4) ve (K = 8, L = 2). Ücret 10 TL, sermayenin kirası 30 TL ise en ucuz bileşim hangisidir?', 'Birinci bileşim', ['İkinci bileşim', 'Üçüncü bileşim', 'Üçü de aynı maliyetlidir.'], 'Maliyetler sırasıyla 60 + 80 = 140, 120 + 40 = 160 ve 240 + 20 = 260 TL\'dir; sermaye pahalı olduğundan emek yoğun bileşim seçilir.'),
  ('Bir fırında ücret işçi başına günlük 1.000 TL, ek işçinin marjinal ürünü 200 ekmektir. Bu aralıkta bir ekmeğin marjinal maliyeti kaç TL\'dir?', '5', ['200', '0,2', '50'], 'Kısa dönemde MC = w / MPL = 1.000 / 200 = 5 TL.'),
  ('Tek değişken girdisi emek olan bir atölyede günlük ücret 600 TL, emeğin ortalama ürünü 30 birimdir. Ortalama değişken maliyet kaç TL\'dir?', '20', ['30', '18.000', '200'], 'AVC = w / APL = 600 / 30 = 20 TL.'),
  ('Kısa dönemde emeğin marjinal ürünü en yüksek düzeyindeyken marjinal maliyet için ne söylenebilir?', 'En düşük düzeyindedir.', ['En yüksek düzeyindedir.', 'Ortalama sabit maliyete eşittir.', 'Sıfırdır.'], 'MC = w / MPL olduğundan ücret sabitken marjinal ürünün zirvesi marjinal maliyetin dibine karşılık gelir.'),
  ('Emeğin ortalama ürününün en yüksek olduğu üretim düzeyi maliyet eğrilerinde hangi noktaya karşılık gelir?', 'Ortalama değişken maliyetin en düşük noktasına', ['Ortalama sabit maliyetin en düşük olduğu ve sıfıra yaklaştığı noktaya', 'Toplam maliyetin en yüksek noktasına', 'Marjinal maliyetin en yüksek noktasına'], 'AVC = w / APL olduğundan APL en yüksekken AVC en düşüktür; ürün ve maliyet eğrileri birbirinin aynası gibidir.'),
  ('Ücretler %10 artarken emek verimliliği de %10 artarsa, emek tek değişken girdiyse birim emek maliyeti nasıl değişir?', 'Değişmez.', ['%10 artar.', '%10 azalır.', '%20 artar.'], 'Birim emek maliyeti = ücret / verimlilik; pay ve payda aynı oranda arttığı için oran sabit kalır.'),
  ('Kârını en çoklaştıran bir firmada hem emek hem sermaye için marjinal ürün değerleri girdi fiyatlarına eşitse (VMP = girdi fiyatı), firmanın maliyet açısından durumu nedir?', 'Ürettiği miktarı en düşük maliyetle üretiyordur.', ['Maliyetini en aza indirmemiştir; girdi bileşimini değiştirmelidir.', 'Zarar ediyordur.', 'Üretimini iki katına çıkarmalıdır.'], 'P·MPL = w ve P·MPK = r ise MPL/w = MPK/r = 1/P olur; bu maliyet minimizasyonu koşuludur.'),
  ('Bir firmanın ürettiği miktarın, kısa dönem ortalama toplam maliyetinin en düşük olduğu miktara eşit olmasına iktisatta genellikle ne ad verilir?', 'Tesisin (teknik) kapasite düzeyi', ['Başabaş noktası', 'Kapanma noktası', 'Doygunluk noktası'], 'Ekonomik anlamda kapasite, tesisin birim maliyetinin en düşük olduğu çıktıdır; bunun altında üretim atıl kapasite anlamına gelir.'),
  ('Talebin Q = 200 − 4P olduğu bir piyasada fiyat 25 TL ise tüketici rantı kaç TL\'dir?', '1.250', ['2.500', '625,0', '5.000'], 'P = 25\'te Q = 100; tüketicilerin ödemeye razı olduğu en yüksek fiyat 50 TL\'dir. Rant ½ × 100 × (50 − 25) = 1.250 TL.'),
  ('Talebin Qd = 100 − P, arzın Qs = P olduğu bir piyasada üreticilere birim başına 10 TL sübvansiyon verilirse alıcıların ödediği fiyat kaç TL olur?', '45 TL', ['50 TL', '55 TL', '40,5 TL'], 'Üreticinin aldığı fiyat alıcınınkinden 10 TL fazladır: 100 − Pb = Pb + 10 ⇒ Pb = 45, Ps = 55, Q = 55.'),
  ('Aynı sübvansiyonlu piyasada (Qd = 100 − P, Qs = P, birim sübvansiyon 10 TL) sübvansiyonun devlete toplam maliyeti ve yarattığı ölü ağırlık kaybı nedir?', '550 TL ve 25 TL', ['500 TL ve 50 TL', '550 TL ve 50,0 TL', '450 TL ve 25 TL'], 'Sübvansiyonlu miktar 55\'tir: maliyet 10 × 55 = 550 TL. Ölü ağırlık ½ × 10 × (55 − 50) = 25 TL\'dir.'),
  ('Sübvansiyon neden çoğu zaman bir ölü ağırlık kaybı yaratır?', 'Malın tüketicilerin değerlemesinden daha yüksek maliyetle fazladan üretilmesine yol açtığı için', ['Tüketicilerin malı daha az almasına yol açtığı için', 'Üreticilerin kârını ve piyasaya giriş isteğini azalttığı için', 'Fiyatı yükselttiği için'], 'Sübvansiyonla denge miktarının üzerine çıkılır; ek birimlerin üretim maliyeti alıcıların ödeme isteğini aşar.'),
  ('Bir malın üretimine 80 birimlik bir kota konuyor; kota olmasaydı piyasa 100 birimde dengede olacaktı. Kotanın fiyat ve refah üzerindeki etkisi hangisidir?', 'Fiyat yükselir ve ölü ağırlık kaybı oluşur.', ['Fiyat düşer ve refah artar.', 'Fiyat ve miktar değişmez.', 'Fiyat düşer ama yine de bir ölü ağırlık kaybı oluşur.'], 'Kota miktarı dengenin altına zorlar; kıt arz fiyatı yükseltir ve gerçekleşmeyen karşılıklı yararlı alışverişler ölü ağırlık kaybıdır.'),
  ('Talebin P = 60 − Q, arzın P = Q olduğu bir piyasada üretici rantı kaç TL\'dir?', '450', ['900', '300', '1.800'], 'Denge P = Q = 30\'dur; üretici rantı ½ × 30 × 30 = 450 TL.'),
  ('Arz eğrisi tamamen yatay (tam esnek) olan bir piyasada üretici rantı kaçtır?', 'Sıfırdır.', ['Tüketici rantına eşittir.', 'Sonsuzdur.', 'Toplam hasılata eşittir.'], 'Her birim tam olarak arz fiyatından satılır; satıcıların kabul edeceği en düşük fiyat ile aldıkları fiyat arasında fark yoktur.'),
  ('Saat ücreti 50 TL olan ve günde 24 saati bulunan, ayrıca günlük 200 TL emek dışı geliri olan bir kişinin \'tam geliri\' kaç TL\'dir?', '1.400', ['1.200', '200', '1.000'], 'Tam gelir, bütün zamanın ücretle değerlenmesi ve emek dışı gelirin eklenmesiyle bulunur: 24 × 50 + 200 = 1.400 TL.'),
  ('Boş zamanın normal mal olduğu bir çalışanın saat ücreti artınca gelir etkisi çalışma saatlerini nasıl etkiler?', 'Azaltır.', ['Artırır.', 'Etkilemez.', 'Önce artırır sonra azaltır.'], 'Daha yüksek ücret daha yüksek gelir demektir; normal mal olan boş zamana daha çok talep doğar ve çalışma saatleri azalır.'),
  ('Bir işveren çalışanlarına \'ya günde tam 8 saat çalışırsın ya da hiç çalışmazsın\' seçeneği sunuyorsa, bu durum emek-boş zaman analizinde neye yol açar?', 'Bütçe kümesini iki noktaya indirerek bazı çalışanları tercih etmedikleri bir noktaya iter.', ['Bütçe doğrusunu dışa doğru paralel kaydırır.', 'Ücretin bütçe doğrusundaki etkisini ortadan kaldırır.', 'Çalışanların faydasını her zaman ve her koşulda artırır; çünkü belirsizlik azalır.'], 'Saat seçimi sınırlanınca kişi kendi optimal saatini seçemez; ya fazla çalışır ya da hiç çalışmaz.'),
  ('Bir öğrencinin bu yıl geliri 20.000 TL, gelecek yıl 33.000 TL\'dir; faiz %10\'dur. Gelecek yılın tüm gelirini bugün borçlanarak harcamak isterse bugün en fazla kaç TL tüketebilir?', '50.000', ['53.000', '56.300,0', '40.000'], 'Bugünkü en yüksek tüketim, ömür boyu gelirin bugünkü değeridir: 20.000 + 33.000 / 1,10 = 20.000 + 30.000 = 50.000 TL.'),
  ('İki dönemli modelde kişinin faiz oranında istediği kadar borç alıp verebildiği durumda Irving Fisher\'ın ayrım teoremi neyi söyler?', 'Yatırım kararlarının kişisel zaman tercihlerinden bağımsız olarak verilebileceğini', ['Tüketimin her dönem gelire eşit olması gerektiğini', 'Faiz oranının tüketicinin kişisel tercihleri tarafından tek başına belirlendiğini', 'Tasarrufun her zaman sıfır olduğunu'], 'Mükemmel sermaye piyasasında önce bugünkü değer en çoklaştırılır, ardından borç alma ya da verme ile istenen tüketim zamanlaması seçilir.'),
  ('Deprem gibi aynı anda pek çok sigortalıyı birden etkileyen riskler, sigorta şirketleri için neden daha zor sigortalanır?', 'Hasarlar birbirinden bağımsız olmadığı için risk havuzlanarak dağıtılamaz.', ['Depremlerin beklenen hasarı sıfırdır.', 'Sigortalılar bu riski önemsemez.', 'Bu riskler aktüeryal olarak adil fiyatlandırılamaz, çünkü olasılıkları sıfırdır.'], 'Büyük sayılar etkisi bağımsız risklerde işler; ortak bir şok bütün poliçeleri birlikte vurduğunda şirket büyük bir toplam kayıpla karşılaşır.'),
  ('Beklenen fayda kuramında fayda fonksiyonuna pozitif doğrusal bir dönüşüm (örneğin v = 3u + 10) uygulanması piyangolar arasındaki tercih sıralamasını nasıl etkiler?', 'Değiştirmez.', ['Tersine çevirir.', 'Yalnızca riskli piyangoların sırasını değiştirir.', 'Kişiyi riske karşı nötr hâle getirir.'], 'Von Neumann-Morgenstern faydası pozitif doğrusal dönüşümlere kadar tektir; doğrusal olmayan monoton dönüşümler ise risk tutumunu değiştirebilir.'),
  ('Riskten kaçınan iki kişi bağımsız ve aynı büyüklükteki risklerinin sonuçlarını eşit paylaşmayı kabul ederse ne olur?', 'Her birinin karşılaştığı risk azalır ve ikisinin de beklenen faydası artar.', ['Beklenen değerleri yarıya düşer.', 'Her birinin karşılaştığı risk iki katına çıkar ve fayda düşer.', 'İkisinin de beklenen faydası azalır.'], 'Risk paylaşımı beklenen değeri değiştirmeden sonuçların değişkenliğini azaltır; riskten kaçınanlar için bu bir kazançtır.'),
  ('Sağlık sigortasında hastanın masrafın belli bir yüzdesini kendisinin ödemesine (katkı payı) ne ad verilir?', 'Müşterek sigorta (katılım payı)', ['Muafiyet tutarı', 'Teminat limiti', 'Prim iadesi (hasarsızlık indirimi)'], 'Katılım payında sigortalı her harcamanın belirli bir oranını üstlenir; muafiyette ise ilk belirli tutarı tümüyle kendisi öder.'),
  ('Fayda fonksiyonu U = x + 2y olan bir tüketici için X\'in fiyatı 1 TL\'dir. Y\'nin fiyatı hangi değerde tüketici iki mal arasında kayıtsız kalır?', '2 TL', ['1 TL', '0,5 TL', '3 TL'], 'Lira başına fayda X için 1/1, Y için 2/Py\'dir; ikisinin eşit olması için Py = 2 TL olmalıdır.'),
  ('Fayda fonksiyonu U = min(x, y), geliri 120 TL olan bir tüketicide iki malın fiyatı da 2 TL\'dir. X\'in fiyatı 4 TL\'ye çıkarsa Y talebi ne olur?', '30\'dan 20\'ye düşer.', ['30\'da kalır.', '30\'dan 40\'a çıkar; Y göreli ucuzlar.', '60\'tan 30\'a düşer.'], 'Önce 120 / (2 + 2) = 30, sonra 120 / (4 + 2) = 20 birim alınır; tam tamamlayıcılarda X\'in pahalanması Y talebini de düşürür.'),
  ('Çay ve simit tüketiminde Cobb-Douglas tercihleri olan Ece için simidin fiyatı artarsa Ece\'nin aldığı çay miktarı nasıl değişir?', 'Değişmez.', ['Artar.', 'Azalır.', 'Sıfıra iner.'], 'Cobb-Douglas\'ta çay talebi a·m/p_çay biçimindedir ve simidin fiyatını içermez; çapraz fiyat etkisi sıfırdır.'),
  ('U = x^0,2 · y^0,3 · z^0,5 fayda fonksiyonuna sahip bir tüketici gelirinin yüzde kaçını Z malına harcar?', '50', ['30', '20', '33,3'], 'Üsleri toplamı 1 olan Cobb-Douglas faydada her mala gelirin üssü kadar payı harcanır; Z\'nin payı %50\'dir.'),
  ('U = x·y faydasına sahip bir tüketicinin geliri 100 TL, X\'in fiyatı 2 TL, Y\'nin fiyatı 5 TL\'dir. Dengede gelirin marjinal faydası (Lagrange çarpanı, MUx/Px) kaçtır?', '5', ['10', '2,5', '25'], 'Denge sepeti x = 25, y = 10\'dur. MUx = y = 10 olduğundan MUx/Px = 10/2 = 5.'),
  ('U = x·y için dolaylı fayda fonksiyonu v = m² / (4·px·py)\'dir. Gelir 100 TL, px = 2 TL ve py = 5 TL iken tüketicinin ulaşabileceği en yüksek fayda kaçtır?', '250', ['500', '125', '1.000'], '10.000 / (4 × 2 × 5) = 10.000 / 40 = 250; bu değer dengedeki 25 × 10 sepetinin faydasına eşittir.'),
  ('Gelirin marjinal faydası (Lagrange çarpanı) tüketici optimizasyonunda neyi ölçer?', 'Bütçe kısıtının bir lira gevşemesinin faydada yarattığı artışı', ['Bir malın fiyatının bir lira artmasının harcamayı ne kadar artırdığını', 'Tüketicinin toplam faydasını', 'İki malın göreli fiyatını'], 'Lagrange çarpanı kısıtın gölge fiyatıdır; bir liralık ek gelirle elde edilecek ek faydayı gösterir.'),
  ('Bir tüketici tam ikame iki mal arasında (U = x + y) seçim yaparken gelir artarsa gelir-tüketim eğrisi nasıl olur (X daha ucuzken)?', 'X ekseni boyunca uzanan yatay bir doğru', ['Orijinden çıkan 45 derecelik doğru', 'Y ekseni boyunca uzanan dikey bir doğru', 'Geriye doğru bükülen ve X eksenine yaklaşan bir eğri'], 'X daha ucuz olduğu sürece bütün gelir X\'e harcanır; gelir arttıkça yalnızca X miktarı büyür ve eğri X ekseni üzerinde kalır.'),
  ('Tam tamamlayıcı iki mal (U = min(x, y)) için gelir-tüketim eğrisi nasıldır?', 'Köşe noktalarından geçen, orijinden çıkan bir doğru', ['X ekseni üzerinde uzanan ve hiç Y içermeyen yatay bir doğru', 'Negatif eğimli bir doğru', 'Y ekseni üzerinde dikey bir doğru'], 'Gelir ne olursa olsun x = y korunur; optimal sepetler 45 derecelik doğru üzerinde dizilir.'),
  ('Fiyat değişikliğinden sonra yalnızca ikame etkisine (Hicks talebine) bakılarak tanımlanan ikame ya da tamamlayıcılık ilişkisine ne ad verilir?', 'Net (Hicks) ikame-tamamlayıcılık', ['Brüt ikame-tamamlayıcılık', 'Çapraz gelir ilişkisi', 'Ortak arz ve birleşik ürün ilişkisi'], 'Net ilişki gelir etkisinden arındırılmıştır ve simetriktir; brüt ilişki ise gelir etkisini de içerdiği için simetrik olmayabilir.'),
  ('Bütçe doğrusunun her yerinde MUx/Px > MUy/Py olan bir tüketicinin faydasını artırmak için X\'e ek bir lira ayırmasının sınırı nedir?', 'Gelirinin tamamını X\'e harcamış olması', ['X\'in marjinal faydasının sıfırlanması ve negatife dönmesi', 'Y\'nin fiyatının düşmesi', 'X\'in fiyatının yükselmesi'], 'Lira başına fayda her yerde X\'te yüksekse tüketici Y\'den tamamen vazgeçip bütçenin izin verdiği kadar X alır; köşe çözümüne ulaşır.'),
  ('Ücret yükselirken sermayenin kirası ve firmanın toplam harcaması sabit kalırsa eş maliyet doğrusu (yatay eksende emek) nasıl değişir?', 'Sermaye eksenindeki noktası sabit kalarak içe döner.', ['Dışa doğru paralel kayar.', 'Emek eksenindeki noktası sabit kalarak dışa doğru döner ve yatıklaşır.', 'Değişmez.'], 'Aynı bütçeyle alınabilecek en fazla emek azalır, en fazla sermaye ise değişmez; doğru dikleşir.'),
  ('Belirli bir bütçeyle çıktıyı en çoklaştırmak isteyen firmanın girdi seçimi, belirli bir çıktıyı en düşük maliyetle üretmek isteyen firmanınkinden nasıl ayrılır?', 'Ayrılmaz; ikisinde de eş ürün eğrisi eş maliyet doğrusuna teğettir.', ['Bütçe kısıtlı problemde MRTS sıfıra eşitlenir ve teğetlik koşulu aranmaz.', 'Bütçe kısıtında yalnızca emek kullanılır.', 'Bütçe kısıtında girdiler eşit miktarda kullanılır.'], 'İki problem birbirinin ikizidir (dualdir); her ikisinde de en iyi nokta MRTS = w/r koşulunu sağlar.'),
  ('Q = 20√L üretim fonksiyonuna sahip bir firmada ürün fiyatı 5 TL, ücret 10 TL\'dir. Kârını en çoklaştıran firma kaç birim emek kullanır?', '25', ['5', '100', '50'], 'MPL = 10/√L; marjinal ürün değeri 50/√L = 10 olmalıdır. Buradan √L = 5 ve L = 25 bulunur.'),
  ('Aynı firmada (Q = 20√L, ürün fiyatı 5 TL, ücret 10 TL, sabit maliyet yok) en yüksek kâr kaç TL\'dir?', '250', ['500', '100', '375,0'], 'L = 25\'te Q = 100; hasılat 500 TL, ücret gideri 250 TL ve kâr 250 TL\'dir.'),
  ('Q = K^0,6 · L^0,6 üretim fonksiyonu için hangi nitelendirme doğrudur?', 'Her girdide azalan marjinal verim, ölçeğe göre artan getiri', ['Her girdide artan marjinal verim, ölçeğe göre sabit getiri', 'Her girdide sabit marjinal verim, ölçeğe göre azalan getiri', 'Her girdide artan marjinal verim, ölçeğe göre de artan getiri vardır'], 'Tek tek üsler 1\'den küçük olduğu için marjinal ürünler azalır; üslerin toplamı 1,2 > 1 olduğu için ölçeğe göre artan getiri vardır.'),
  ('Cobb-Douglas üretim fonksiyonunda ölçek esnekliği (ölçeğe göre getiri derecesi) nasıl bulunur?', 'Girdilerin çıktı esnekliklerinin, yani üslerin toplanmasıyla', ['Üslerin çarpılmasıyla', 'Teknoloji katsayısının üslerin toplamına ve çarpımına bölünmesiyle', 'Emeğin üssünden sermayenin üssünün çıkarılmasıyla'], 'Bütün girdiler %1 artınca çıktı, çıktı esneklikleri toplamı kadar yüzde artar; Cobb-Douglas\'ta bu üslerin toplamıdır.'),
  ('Q = K^0,5 · L^0,5 eş ürün eğrileri ile Q = K + L eş ürün eğrileri arasındaki önemli fark hangisidir?', 'Birincisi eksenlere hiç değmez; ikincisi eksenleri keser.', ['Birincisi doğrusaldır, ikincisi ise orijine göre dışbükeydir.', 'İkisi de eksenleri keser.', 'Birincisi L biçimli, ikincisi dışbükeydir.'], 'Cobb-Douglas\'ta her iki girdi de zorunlu olduğundan eğriler eksenlere asimptotik yaklaşır; doğrusal teknolojide tek girdiyle üretim mümkündür.'),
  ('Q = min(L/2, K) üretim fonksiyonunda 30 birim çıktıyı israfsız üretmek için kaç birim emek gerekir?', '60', ['30', '15', '120,0'], 'Her çıktı birimi için 2 birim emek ve 1 birim sermaye gerekir: L = 2 × 30 = 60.'),
  ('Sermayenin sabit olduğu kısa dönemde (yatay eksende emek) firmanın genişleme yolu nasıl görünür?', 'Sabit sermaye düzeyinde yatay bir doğru', ['Orijinden geçen ve sermayeyi de artıran bir ışın', 'Dikey bir doğru', 'Negatif eğimli bir doğru'], 'Kısa dönemde çıktı yalnızca emek artırılarak büyütülebilir; bu yüzden girdi bileşimleri sabit K düzeyinde yatay bir çizgi üzerinde dizilir.'),
  ('Bir firmanın kısa dönem toplam maliyeti, tesisin planlandığı çıktıdan farklı bir çıktı üretilirken uzun dönem toplam maliyetle nasıl karşılaştırılır?', 'Kısa dönem maliyeti daha yüksektir.', ['Kısa dönem maliyeti daha düşüktür.', 'İkisi her zaman ve her çıktı düzeyinde birbirine eşittir.', 'Kısa dönem maliyeti sıfırdır.'], 'Tesis o çıktı için en uygun büyüklükte değilse kısa dönemde aynı çıktı uzun dönemdeki en iyi tesisten daha pahalıya üretilir.'),
  ('Kâr fonksiyonu π(p, w) ürün fiyatı ve ücretin bir fonksiyonu olarak yazılırsa, bütün fiyatlar iki katına çıktığında kâra ne olur?', 'İki katına çıkar.', ['Değişmez.', 'Dört katına çıkar.', 'Yarıya iner.'], 'Kâr fonksiyonu fiyatlarda birinci dereceden homojendir; göreli fiyatlar değişmediğinden üretim planı aynı kalır ama tutarlar iki katına çıkar.'),
  ('Bir girdinin kullanımı arttıkça diğer girdinin marjinal ürünü de artıyorsa (örneğin daha çok bilgisayar işçinin verimini artırıyorsa) bu girdiler arasındaki ilişki üretimde nasıl adlandırılır?', 'Tamamlayıcı girdiler', ['İkame girdiler', 'Bağımsız (ilişkisiz) girdiler', 'Düşük girdiler'], 'Çapraz marjinal ürünün pozitif olması, bir girdinin artışının diğerinin verimini yükselttiğini, yani girdilerin tamamlayıcı olduğunu gösterir.'),
  ('Beklenen değeri bilet fiyatından düşük olan piyango biletlerini düzenli alan bir kişinin davranışı standart beklenen fayda kuramında en kolay nasıl açıklanır?', 'Bu kişinin söz konusu tutarlarda riski seven bir fayda fonksiyonu olduğu varsayılarak', ['Bu kişinin riskten çok kaçındığı varsayılarak', 'Bu kişinin geçişli tercihleri olmadığı ve sıralama yapamadığı varsayılarak bu davranış açıklanır', 'Bu kişinin geliri olmadığı varsayılarak'], 'Adil olmayan bir kumarı kabul etmek, en azından o bölgede dışbükey (risk seven) bir fayda fonksiyonunu gerektirir.'),
  ('Bir şirket yöneticisi \'üretim fonksiyonumuz ölçeğe göre artan getiri gösteriyor, bu yüzden azalan verimler kanunu bizim için geçersizdir\' diyor. Bu görüş için en doğru değerlendirme hangisidir?', 'Yanlıştır; ölçeğe göre artan getiri varken de tek bir girdi artırıldığında azalan verim görülebilir.', ['Doğrudur; iki kavram birbirinin tersidir.', 'Doğrudur; artan getiride marjinal ürünler hep artar.', 'Yanlıştır; çünkü ölçeğe göre artan getiri yalnızca kısa dönemde ve tek girdi değiştiğinde görülebilir.'], 'Ölçek getirisi bütün girdilerin birlikte değişimine, azalan verim ise tek girdinin değişimine ilişkindir; ikisi bir arada bulunabilir.'),
  ('Bir aile \'tasarruf hesabımızın faizi yükseldi, artık daha az biriktirsek de hedefe ulaşırız\' diyerek bugünkü harcamalarını artırıyor. Bu davranış Fisher modelinde hangi etkinin baskın olduğunu gösterir?', 'Gelir etkisinin', ['İkame etkisinin', 'Para yanılsamasının', 'Batık maliyet etkisinin'], 'Faiz artışı tasarruf sahibini zenginleştirir; gelir etkisi bugünkü tüketimi artırır. İkame etkisi ise tersine, tasarrufu teşvik ederdi.'),
  ('Bir tüketici kuramı öğrencisi \'Giffen malları gerçek hayatta görülmez, çünkü talep kanunu evrenseldir\' diyor. Bu iddia için en doğru değerlendirme hangisidir?', 'Kuramsal olarak Giffen malı mümkündür ve bazı yoksul hanelerde temel gıdalarda gözlenmiştir.', ['Doğrudur; talep kanunu hiçbir istisna kabul etmez.', 'Doğrudur; Giffen malları yalnızca pahalı lüks mallar arasında görülür ve temel gıdalarda hiçbir zaman görülmez.', 'Yanlıştır; çünkü bütün düşük mallar Giffen malıdır.'], 'Talep kanunu Slutsky ayrıştırmasından türeyen bir eğilimdir; güçlü negatif gelir etkisi onu tersine çevirebilir.'),
  ('Bir belediye \'yaşlılara her ay ücretsiz kömür dağıtmak, aynı değerde nakit vermekten her zaman daha iyidir\' diyor. Tüketici kuramına göre bu görüş için en doğru değerlendirme hangisidir?', 'Yaşlıların refahı açısından nakit en az kömür kadar iyidir; ayni yardımın gerekçesi başka amaçlara dayanmalıdır.', ['Doğrudur; ayni yardım tüketicinin seçimini yönlendirdiği için her zaman daha yüksek fayda sağlar ve israfı önler.', 'Doğrudur; çünkü kömür bir Giffen malıdır.', 'Yanlıştır; nakit yardım her zaman faydayı düşürür.'], 'Nakit bütçe kümesini daha çok genişletir; ayni yardım ancak kömür tüketimini artırmak gibi ayrı bir sosyal amaç güdülüyorsa savunulabilir.'),
  ('Talebin Qd = 100 − 2P + 0,5M (M gelir), arzın Qs = 3P olduğu bir piyasada gelir 40\'tan 60\'a çıkarsa denge fiyatı kaç TL artar?', '2', ['4', '10', '1,5'], 'M = 40\'ta 120 − 2P = 3P ⇒ P = 24; M = 60\'ta 130 − 2P = 3P ⇒ P = 26. Fiyat 2 TL artar.'),
  ('Bir piyasada aynı anda talep artar ve arz azalırsa yeni dengede kesin olarak ne söylenebilir?', 'Fiyat yükselir; miktarın yönü belirsizdir.', ['Miktar kesin olarak artar; fiyatın yönü ise belirsizdir.', 'Fiyat düşer ve miktar azalır.', 'Fiyat ve miktar değişmez.'], 'İki kayma da fiyatı yükseltir; miktar ise talep artışıyla artarken arz azalışıyla düşer, net etki kaymaların büyüklüğüne bağlıdır.'),
  ('Bu yıl 50.000 TL, gelecek yıl 55.000 TL geliri olan biri faiz oranı %10 iken bu yıl 60.000 TL tüketmek isterse gelecek yıl en fazla kaç TL tüketebilir?', '44.000', ['45.000', '55.000', '49.500,0'], '10.000 TL borç alır ve gelecek yıl 11.000 TL geri öder: 55.000 − 11.000 = 44.000 TL.'),
  ('Fayda fonksiyonu u(w) = √w olan bir kişi kesin 49 TL ile %50 olasılıkla 25 TL, %50 olasılıkla 100 TL arasında seçim yapıyor. Hangisini seçer?', 'Piyangoyu', ['Kesin 49 TL\'yi', 'İkisine kayıtsız kalır.', 'Kesin tutarı; çünkü riskten kaçınan kişi her zaman kesini seçer.'], 'Piyangonun beklenen faydası 0,5 × 5 + 0,5 × 10 = 7,5, kesin tutarınki √49 = 7\'dir. Riskten kaçınsa da piyangonun beklenen değeri (62,5) yeterince yüksektir.'),
  ('u(w) = √w fayda fonksiyonuna sahip birinin %50 olasılıkla 36 TL, %50 olasılıkla 100 TL veren piyangosu için risk primi kaç TL\'dir?', '4', ['8', '32', '68'], 'Beklenen değer 68, beklenen fayda 0,5 × 6 + 0,5 × 10 = 8\'dir; kesinlik eşdeğeri 64 TL olur. Risk primi 68 − 64 = 4 TL\'dir.'),
  ('Kazanç olarak sunulan seçimlerde riskten kaçınan insanların, aynı seçimler kayıp olarak sunulunca riski göze almasına beklenti kuramında ne ad verilir?', 'Yansıma etkisi', ['Tuzak etkisi', 'Sahiplik etkisi', 'Çapalama etkisi'], 'Yansıma etkisi, değer fonksiyonunun kazançlarda içbükey, kayıplarda dışbükey olmasının davranıştaki karşılığıdır.'),
  ('Bir ürünün fiyatının 1 TL\'den sıfıra indirilmesinin, 2 TL\'den 1 TL\'ye indirilmesinden çok daha büyük talep artışı yaratması hangi gözlemle ilgilidir?', 'Sıfır fiyat (\'bedava\') etkisi', ['Giffen etkisi', 'Veblen (gösteriş tüketimi) etkisi', 'Ölçek ekonomisi'], 'Davranışsal deneyler, \'bedava\' seçeneğinin standart maliyet-fayda hesabının öngördüğünden çok daha çekici bulunduğunu gösterir.'),
  ('Bir oyun konsolunun değerinin, onun için yazılan oyun sayısı arttıkça yükselmesi hangi tür ağ etkisine örnektir?', 'Dolaylı ağ etkisi', ['Doğrudan ağ etkisi', 'Snop etkisi', 'Negatif ağ etkisi'], 'Konsol kullanıcıları birbirleriyle doğrudan bağlanmasa da kullanıcı sayısı tamamlayıcı ürünlerin (oyunların) artmasını sağlar.'),
  ('Lancaster\'ın nitelikler yaklaşımına göre, bir lira başına her nitelikten başka bir maldan daha az sunan bir mal için ne beklenir?', 'Rasyonel tüketiciler tarafından satın alınmaz.', ['Tüketicilerin en çok tercih ettiği ve en çok satılan mal olur.', 'Mutlaka bir Giffen malıdır.', 'Fiyatı düştükçe talebi azalır.'], 'Başka bir mal her nitelikte daha fazlasını sunuyorsa bu mal etkin sınırın içinde kalır; fiyatı düşmedikçe seçilmez.'),
  ('Gary Becker\'ın yaklaşımında hanenin, piyasadan alınan mallarla kendi zamanını birleştirerek \'yemek yemek\' ya da \'çocuk yetiştirmek\' gibi çıktılar üretmesi neyi gösterir?', 'Hanenin de bir üretim fonksiyonu olduğunu', ['Hanenin yalnızca tüketim yaptığını', 'Hanenin zamanının bir değeri olmadığını', 'Hanenin her zaman piyasadan hazır mal aldığını'], 'Becker\'a göre hane küçük bir fabrika gibidir; zaman ve mallar birleştirilerek faydayı doğrudan sağlayan temel ürünler üretilir.'),
  ('John Hicks\'in 1932\'de ortaya attığı \'uyarılmış yenilik\' fikrine göre bir üretim faktörünün göreli olarak pahalanması neye yol açar?', 'O faktörden tasarruf ettiren teknolojilerin geliştirilmesine', ['O faktörün daha çok kullanılmasına', 'Teknolojik ilerlemenin tamamen durmasına ve eski yöntemlere dönülmesine', 'Bütün faktör fiyatlarının eşitlenmesine'], 'Göreli fiyat değişimleri yenilikçileri pahalanan girdiyi daha az kullanan yöntemler aramaya yöneltir.'),
  ('Bir firmanın yöneticileri \'kâr marjımız yeterli, maliyet kontrolüne gerek yok\' diyerek rakiplerden daha yüksek maliyetle üretmeye devam ediyor. Rekabetin yoğunlaşması bu firmayı nasıl etkiler?', 'Maliyetlerini düşürmeye ya da piyasadan çıkmaya zorlar.', ['Hiçbir etkisi olmaz.', 'Firmanın kârını kesin olarak artırır.', 'Firmanın üretim teknolojisini değiştirmeden fiyatlarını yükseltmesine imkân verir.'], 'Rekabet baskısı, X-etkinsizliği gibi gevşekliklerin sürdürülmesini zorlaştırır; yüksek maliyetli firma ya etkinleşir ya küçülür.'),
  ('Bir otomobil seçerken tüketicilerin yakıt tasarrufu, güvenlik ve bagaj hacmi gibi özelliklere fiyat biçmesini istatistiksel olarak tahmin eden yöntem hangi yaklaşıma dayanır?', 'Hedonik fiyatlama', ['Maliyet artı fiyatlama', 'Tavan fiyat uygulaması', 'Başabaş analizi'], 'Hedonik modeller bir ürünün fiyatını niteliklerine ayırır; Lancaster\'ın nitelikler fikrinin ampirik uygulamasıdır.'),
  ('Slutsky denklemine göre bir malın Hicks talebinin fiyata göre türevi −2, tüketilen miktar 10 ve talebin gelire göre türevi 0,3 ise Marshall talebinin fiyata göre türevi kaçtır?', '−5', ['−2', '1', '−2,3'], '∂x/∂p = ∂h/∂p − x·∂x/∂m = −2 − 10 × 0,3 = −5.'),
  ('Bir malın fiyatı yükseldiğinde, o malın net satıcısı olan bir tüketicinin refahı için ne söylenebilir?', 'İyileşir; satıcı olmaya devam ederse en az eskisi kadar iyidir.', ['Kesinlikle kötüleşir.', 'Hiç değişmez.', 'Yalnızca malın lüks mal olması durumunda iyileşir.'], 'Eski sepet yeni fiyatlarda hâlâ alınabilir, üstelik satılan kısım daha değerlidir; bu yüzden net satıcının refahı azalmaz.'),
  ('Donatıma dayalı bir modelde (tüketici gelirini mallarını satarak elde ediyor) bütçe doğrusu fiyatlar değişince hangi nokta etrafında döner?', 'Tüketicinin başlangıçtaki donatım noktası', ['Orijin', 'X ekseninin bütçe doğrusuyla kesiştiği nokta', 'Tüketicinin optimal sepeti'], 'Donatım sepeti her fiyatta satın alınabilir (değeri her zaman gelire eşittir); bu yüzden bütçe doğrusu ondan geçer.'),
  ('Kısa dönemde ücretler yükselirse firmanın maliyet eğrilerinden hangisi değişmeden kalır?', 'Ortalama sabit maliyet', ['Marjinal maliyet', 'Ortalama değişken maliyet', 'Ortalama toplam maliyet'], 'Ücret değişken maliyetin bir parçasıdır; MC, AVC ve ATC yukarı kayar, sabit maliyet ve dolayısıyla AFC değişmez.'),
  ('Marjinal maliyet artarken ortalama toplam maliyet hâlâ azalıyor olabilir mi?', 'Evet; marjinal maliyet ortalamanın altında kaldığı sürece ortalama düşer.', ['Hayır; marjinal maliyet artmaya başlar başlamaz ortalama maliyet de hemen artar.', 'Hayır; iki eğri her zaman aynı yönde hareket eder.', 'Evet; ama yalnızca sabit maliyet sıfırsa.'], 'Ortalamanın yönünü marjinalin ortalamadan büyük ya da küçük olması belirler; marjinalin artıp azalması belirlemez.'),
  ('Bir firmanın büyüdükçe hammaddeyi toplu alarak tedarikçilerden indirim alması nasıl bir ölçek ekonomisidir?', 'Parasal (pekuniyer) ölçek ekonomisi', ['Teknik (reel) ölçek ekonomisi', 'Kapsam ekonomisi', 'Öğrenme ekonomisi'], 'Parasal ölçek ekonomileri girdi fiyatlarının düşmesinden doğar; üretim teknolojisi değişmez.'),
  ('Bir makinenin yıl başında piyasa değeri 100.000 TL, yıl sonunda 70.000 TL\'dir. Muhasebede yıllık amortisman 20.000 TL ayrılmışsa bu yılın ekonomik amortisman maliyeti kaç TL\'dir?', '30.000', ['20.000', '10.000', '70.000,0'], 'Ekonomik amortisman makinenin piyasa değerindeki gerçek düşüştür: 100.000 − 70.000 = 30.000 TL.'),
  ('Emeğin hem marjinal hem ortalama ürününün azaldığı bir aralıkta bu iki büyüklük arasındaki ilişki nedir?', 'Marjinal ürün ortalama üründen küçüktür.', ['Marjinal ürün ortalama üründen büyüktür.', 'İkisi her zaman eşittir.', 'Marjinal ürün sıfırdır ve negatife dönmek üzeredir.'], 'Ortalama ürün ancak marjinal ürün onun altına indiğinde azalır.'),
  ('Bir şirket bir yıl önce 2 milyon TL\'ye bir arsa almış; arsanın bugünkü piyasa değeri 3 milyon TL\'dir. Arsaya fabrika kurmanın ekonomik maliyeti hesaplanırken arsa için hangi tutar esas alınmalıdır?', '3 milyon TL; arsanın bugün satılarak elde edilebilecek değeri', ['2 milyon TL; arsanın alış fiyatı', 'Sıfır; arsa zaten şirketin malı olduğu için maliyet doğurmaz.', '1 milyon TL; değer artışı'], 'Ekonomik karar için fırsat maliyeti önemlidir; arsa fabrikaya ayrılırsa bugünkü piyasa değeri kadar gelirden vazgeçilir.'),
  ('Kısa dönemde bir firmanın üretimi artarken ortalama değişken maliyet ile ortalama toplam maliyet eğrilerinin en düşük noktaları hangi sırayla görülür?', 'Önce ortalama değişken maliyet, sonra ortalama toplam maliyet en düşük düzeye iner.', ['Önce ortalama toplam maliyet, sonra ortalama değişken maliyet en düşük düzeye iner.', 'İkisi aynı üretim düzeyinde en düşük olur.', 'Ortalama toplam maliyetin en düşük noktası yoktur.'], 'ATC = AVC + AFC ve AFC sürekli düştüğü için AVC yükselmeye başladıktan bir süre sonra da ATC düşmeye devam eder; ATC\'nin dibi daha sağdadır.'),
  ('Bir fabrikada kısa dönemde üretim artırıldıkça marjinal maliyetin hızla yükselmesi en çok neye işaret eder?', 'Sabit tesisin kapasite sınırına yaklaşılmasına', ['Ölçek ekonomilerinin başlamasına', 'Sabit maliyetlerin azalmasına', 'Teknolojik ilerlemeye ve verimlilik artışına'], 'Kapasite sınırında her ek birim için giderek daha çok değişken girdi gerekir; azalan verim marjinal maliyeti dikleştirir.'),
  ('Bir malın talep eğrisinin altında, sıfırdan satın alınan miktara kadar kalan toplam alan neyi gösterir?', 'Tüketicilerin o miktar için ödemeye razı oldukları toplam tutarı', ['Üreticilerin toplam maliyetini', 'Devletin vergi gelirini', 'Tüketicilerin o miktar için fiilen ödediği ve kasaya giren tutarı'], 'Her birim için ödeme isteklerinin toplamı brüt tüketici faydasıdır; bundan fiilî harcama çıkarılınca tüketici rantı kalır.'),
  ('Marshall\'ın tüketici rantını talep eğrisinin altındaki alanla ölçmesinin kesin olarak geçerli olması için hangi varsayım gerekir?', 'Paranın marjinal faydasının sabit olması', ['Malın Giffen malı olması', 'Talebin tam esnek ve yatay olması', 'Bütün malların tam tamamlayıcı olması'], 'Paranın marjinal faydası sabitse (gelir etkisi yoksa) Marshall rantı telafi edici ve eşdeğer değişimle çakışır.'),
  ('Gelir arttıkça bir malın hanenin toplam harcamasındaki payı yükseliyorsa bu mal için ne söylenebilir?', 'Gelir esnekliği 1\'den büyüktür; lüks maldır.', ['Gelir esnekliği 0 ile 1 arasındadır; zorunlu maldır.', 'Gelir esnekliği negatiftir.', 'Gelir esnekliği tam olarak 1\'dir.'], 'Harcama payı p·x/m\'dir; payın gelirle artması için miktarın gelirden daha hızlı artması gerekir.'),
  ('Firmanın her olası tesis büyüklüğü için en düşük birim maliyeti gösteren ve yeni bir tesis kurmadan önce kullanılan uzun dönem ortalama maliyet eğrisine verilen diğer ad nedir?', 'Planlama eğrisi', ['Talep eğrisi', 'Lorenz eğrisi', 'Laffer (vergi-gelir) eğrisi'], 'Uzun dönemde firma henüz tesisini seçmediği için LRAC, hangi ölçekte yatırım yapılacağını gösteren bir planlama aracıdır.'),
  ('Kâr maksimizasyonunda MR = MC koşulunun sağlandığı iki farklı çıktı düzeyi varsa, kârın en yüksek olduğu nokta hangisidir?', 'Marjinal maliyetin marjinal hasılatı aşağıdan kestiği, yani MC\'nin daha hızlı yükseldiği nokta', ['Marjinal maliyetin düşmekte olduğu ilk nokta', 'İki noktadan çıktısı küçük olanı; çünkü maliyet orada daha düşüktür.', 'Ortalama maliyetin en yüksek olduğu nokta'], 'İkinci sıra koşulu gereği MC\'nin MR\'den daha dik yükseldiği yerde kâr en yüksektir; MC\'nin düştüğü kesişim noktası kâr minimumudur.'),
  ('Bir tüketicinin geliri ve fiyatlar sabitken zevkleri değişip X\'i Y\'ye göre daha çok sevmeye başlarsa kayıtsızlık eğrileri (yatay eksende X) nasıl değişir?', 'Marjinal ikame oranı artar; eğriler her noktada dikleşir.', ['Eğriler yatıklaşır; X için daha az Y feda edilir.', 'Bütçe doğrusu dışa kayar.', 'Eğriler yatay hâle gelir.'], 'X\'e verilen göreli değer artınca bir birim X için feda edilmeye razı olunan Y miktarı artar; eğriler dikleşir ve tüketici daha çok X seçer.'),
  ('Talep eğrisi tamamen dikey olan bir maldan, fiyat 10 TL arttığında tüketici rantı ne kadar azalır (miktar 50 birim)?', '500 TL', ['250 TL', '50 TL', '1.000 TL'], 'Miktar değişmediğinden kayıp yalnızca dikdörtgen alanıdır: 10 × 50 = 500 TL.'),
  ('Kenneth Arrow\'un 1962 tarihli makalesine göre bir sektörde deneyim biriktikçe verimliliğin artması hangi kavramla adlandırılır?', 'Yaparak öğrenme', ['Ölçeğe göre azalan getiri', 'Uyarılmış yenilik', 'X-etkinsizliği'], 'Arrow, yatırım ve üretim deneyiminin bilgi biriktirerek verimliliği yükselttiğini \'learning by doing\' kavramıyla açıkladı.'),
  ('Bir firmanın çıktısı bir yılda %8, kullandığı girdilerin bileşik endeksi %5 artmıştır. Firmanın toplam faktör verimliliği yaklaşık yüzde kaç artmıştır?', '3', ['13', '8', '1,6'], 'Toplam faktör verimliliği artışı ≈ çıktı artışı − girdi artışı = 8 − 5 = %3.'),
  ('Emek verimliliği (işçi başına çıktı) arttığı hâlde toplam faktör verimliliğinin değişmemesi nasıl mümkün olur?', 'İşçi başına kullanılan sermaye arttığı için', ['İşçiler daha az saat çalıştığı ve dinlendiği için', 'Firmanın ürün fiyatı arttığı için', 'Ücretler düştüğü için'], 'Daha çok makineyle çalışan işçi daha çok üretir; bu artış teknolojideki gelişmeden değil, sermaye derinleşmesinden kaynaklanabilir.'),
  ('Bir sigorta poliçesinde prim ile sigortalının beklenen kaybı arasındaki farka ne ad verilir?', 'Yükleme', ['Muafiyet', 'Katılım payı', 'Tazminat (hasar ödemesi) tutarı'], 'Aktüeryal olarak adil primde yükleme sıfırdır; gerçek poliçelerde idari giderler ve kâr için pozitif bir yükleme bulunur.'),
  ('Riskten kaçınan bir tüketici, primde yükleme olduğunda bile neden yine de bir miktar sigorta alabilir?', 'Riskin azalmasından sağladığı fayda yükleme maliyetini aşabildiği için', ['Yükleme sigortalıya geri ödendiği için', 'Sigorta, primde yükleme olsa bile beklenen serveti her durumda artırdığı için', 'Riskten kaçınan kişiler beklenen değeri önemsemediği için'], 'Risk primi yüklemeden büyükse, beklenen servet biraz düşse de belirsizliğin azalması beklenen faydayı artırır.'),
  ('Bir çiftçi yarın yağmur yağıp yağmayacağını kesin olarak bilseydi ekim kararından 2.000 TL daha fazla beklenen kazanç elde edecektir. Bu tutar neyi ölçer?', 'Kusursuz bilginin beklenen değerini', ['Risk primini ve sigorta yüklemesini', 'Kesinlik eşdeğerini', 'Batık maliyeti'], 'Bilgi olmadan verilen en iyi karar ile bilgiyle verilen kararın beklenen getirisi arasındaki fark, kusursuz bilgi için ödenebilecek en yüksek tutardır.'),
  ('Bir firmanın aynı makinelerle hem küçük hem büyük partiler üretebilmesine rağmen büyük partilerde birim maliyetin düşmesinin nedeni çoğu zaman hangisidir?', 'Makine hazırlama (kurulum) maliyetinin daha çok birime yayılması', ['Marjinal ürünün büyük partilerde negatife dönmesi', 'Ücretlerin artması', 'Talebin azalması'], 'Her parti için katlanılan sabit hazırlık maliyeti büyük partilerde daha çok birime bölünür; birim maliyet düşer.'),
  ('Bir kişinin cüzdanını kaybetmesinin acısının, aynı tutarda para bulmanın sevincinden büyük olduğunu ölçen deneylerde kayıpların kazançlara göre yaklaşık kaç kat ağır tartıldığı bulunmuştur?', 'Yaklaşık 2 kat', ['Yaklaşık 10 kat', 'Yaklaşık 0,5 kat', 'Tam olarak 1 kat'], 'Tversky ve Kahneman\'ın 1992 tahminlerinde kayıptan kaçınma katsayısı yaklaşık 2,25\'tir; genellikle \'yaklaşık iki kat\' diye özetlenir.'),
  ('Q = min(K, L) gibi sabit oranlı bir teknolojiyle üretim yapan bir firmada ücretler iki katına çıkarsa maliyeti en aza indiren girdi oranı (K/L) nasıl değişir?', 'Değişmez; girdiler yine aynı oranda kullanılır.', ['Artar; firma pahalanan emek yerine daha çok sermaye kullanmaya başlar.', 'Azalır; firma daha çok emek kullanır.', 'Sıfıra iner.'], 'Sabit oranlı teknolojide girdiler arasında ikame imkânı yoktur; fiyat değişimi yalnızca maliyeti artırır, bileşimi değiştirmez.'),
  ('Maliyetini en aza indiren ve Q = K^0,25 · L^0,75 teknolojisini kullanan bir firma toplam maliyetinin yüzde kaçını emeğe harcar?', '75', ['25', '50', '100'], 'Cobb-Douglas teknolojide maliyet en aza indirildiğinde her girdinin maliyet payı, üssünün üsler toplamına oranına eşittir: 0,75 / 1 = %75.'),
  ('Günde 16 saati olan, emek dışı geliri bulunmayan ve fayda fonksiyonu U = C^0,75 · L^0,25 olan (L boş zaman) bir kişi günde kaç saat çalışır?', '12', ['4', '8', '10,5'], 'Cobb-Douglas faydada tam gelirin %25\'i boş zamana gider: L = 0,25 × 16 = 4 saat; çalışma 16 − 4 = 12 saattir.'),
  ('Arz fonksiyonu Qs = 4P olan bir piyasada fiyat 10 TL\'den 15 TL\'ye çıkarsa üretici rantı kaç TL artar?', '250', ['50', '200', '450,0'], 'Üretici rantı ½ × P × 4P = 2P²\'dir: önce 200, sonra 450 TL; artış 250 TL\'dir.'),
  ('Tam tamamlayıcı iki mal (U = min(x, y)) için yalnızca X\'in fiyatı değiştiğinde fiyat-tüketim eğrisi nasıl görünür?', 'Orijinden geçen 45 derecelik bir doğru', ['Yatay bir doğru; Y miktarı hiç değişmez.', 'Dikey bir doğru', 'Negatif eğimli bir doğru'], 'Fiyat ne olursa olsun tüketici x = y oranını korur; değişen yalnızca alınan miktarlardır.'),
  ('Belirli bir çıktıyı en düşük maliyetle üreten her firmanın kârını da en çoklaştırdığı söylenebilir mi?', 'Hayır; maliyeti en aza indirmek doğru çıktı düzeyini seçmeyi garanti etmez.', ['Evet; iki kavram tamamen aynıdır.', 'Evet; ama yalnızca kısa dönemde.', 'Hayır; çünkü maliyet minimizasyonu her zaman zarar ettirir ve kârı sıfırlar.'], 'Maliyet minimizasyonu her çıktı düzeyi için yapılabilir; kâr maksimizasyonu ayrıca bunlar arasından MR = MC koşulunu sağlayan çıktıyı seçmeyi gerektirir.'),
  ('Talep fonksiyonları Q₁ = 10 − P ve Q₂ = 20 − 2P olan iki tüketiciden oluşan piyasada fiyat 12 TL olursa toplam talep kaç birimdir?', '0', ['2', '−6', '8'], 'Her iki tüketici de 10 TL\'nin üzerindeki fiyatlarda hiç almaz; negatif talep olmadığı için piyasa talebi sıfırdır.'),
  ('Bir tüketicinin emek dışı geliri artarken çalışma saatlerini artırması, boş zaman için ne gösterir?', 'Boş zamanın bu kişi için düşük mal olduğunu', ['Boş zamanın normal mal olduğunu', 'Ücretin düştüğünü', 'İkame etkisinin gelir etkisinden baskın olduğunu'], 'Saf gelir artışında boş zaman tüketimi azalıyorsa boş zaman düşük maldır; bu, sık görülmeyen bir durumdur.'),
  ('Bir firma ücret %10 artınca toplam maliyetinin yaklaşık %6 arttığını görüyor (çıktı ve sermayenin kirası sabit). Shephard lemmasından hareketle firmanın maliyet içinde emeğe ayırdığı pay yaklaşık nedir?', '%60', ['%10', '%6', '%40,0'], 'Maliyetin ücrete göre esnekliği emeğin maliyet payına eşittir: 6 / 10 = 0,6.'),
];
